window.VRAGEN_DATA=(window.VRAGEN_DATA||[]).concat([
 {id:'vbk-001',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-02T09:25:00',views:562,tags:['inventarisatie','verhoging','passend advies'],beste:'vbk-001-a1',
  titel:'Volledige inventarisatie opnieuw bij verhoging van een bestaande hypotheek?',
  body:`Een bestaande klant wil zijn hypotheek verhogen voor een verbouwing. Twee jaar geleden hebben we een volledige inventarisatie gedaan. Moet ik alles opnieuw uitvragen, of mag ik volstaan met een update van de gewijzigde onderdelen?`,
  antwoorden:[
   {id:'vbk-001-a1',auteur:'u8',datum:'2025-10-03T01:56:00',rA:{u1:4,u3:5,u7:5},rAdv:{u1:4,u2:4,u5:5,u6:5},body:`Je advies moet passend zijn op het moment dat je het geeft, dus je moet weten wat er sinds de vorige inventarisatie is veranderd. Dat hoeft niet per se een compleet nieuw gesprek te zijn, maar je moet elk onderdeel wel actief toetsen.
- Loop inkomen, verplichtingen, gezinssituatie, pensioen, risicobereidheid en doelstellingen opnieuw langs.
- Leg per onderdeel vast of het ongewijzigd is, bevestigd door de klant, en met welke stukken.
- Maak een nieuw klantprofiel aan met de actuele datum.
Alleen verwijzen naar het oude profiel zonder toetsing houdt bij een klacht geen stand.`},
   {id:'vbk-001-a2',auteur:'u4',datum:'2025-10-03T06:04:00',rA:{u1:4,u6:5},rAdv:{},body:`Bij ons gebruiken we de oude inventarisatie als startpunt en lopen we die samen met de klant door. Wat wijzigt, passen we aan; wat gelijk blijft, laat de klant bevestigen. Kijk ook opnieuw naar de risicos bij overlijden en arbeidsongeschiktheid, want een hoger bedrag verandert dat beeld. In het rapport noemen we expliciet dat het profiel is geactualiseerd en op welke datum.`}
  ]},
 {id:'vbk-002',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-05T20:50:00',views:404,tags:['execution only','hypotheek','zorgplicht'],beste:'vbk-002-a1',
  titel:'Mag een klant een hypotheek op execution only basis afsluiten via ons kantoor?',
  body:`Een klant met financiële achtergrond zegt geen advies nodig te hebben en wil alleen dat wij de aanvraag doen. Mag dat, en wat moet ik dan vastleggen? Ik wil voorkomen dat het later toch als advies wordt gezien.`,
  antwoorden:[
   {id:'vbk-002-a1',auteur:'u8',datum:'2025-10-06T18:38:00',rA:{u1:4,u2:4,u3:3,u7:4},rAdv:{u1:3,u3:5,u6:4,u7:3},body:`Execution only is bij hypotheken niet verboden, maar je moet het zuiver inrichten. Het grootste risico is dat je in de praktijk toch adviseert, bijvoorbeeld door een product of looptijd aan te raden. Dan ben je voor advies aansprakelijk zonder dat je een adviesdossier hebt.
- Laat de klant schriftelijk bevestigen dat hij bewust zonder advies kiest.
- Wijs hem op de risicos van die keuze.
- Controleer of je eigen dienstverleningsdocument execution only ook beschrijft.
- Check bij de geldverstrekker of zij execution only aanvragen accepteren en onder welke voorwaarden.`},
   {id:'vbk-002-a2',auteur:'u5',datum:'2025-10-06T22:42:00',rA:{u1:3,u3:4,u6:4,u7:4},rAdv:{u4:5},body:`Ik doe het zelden, en alleen bij klanten die echt weten wat ze doen. Zodra ik merk dat de klant vragen gaat stellen als welke rentevaste periode zou jij kiezen, stop ik en bied ik alsnog advies aan. Dat moment leg ik ook vast in een notitie.`}
  ]},
 {id:'vbk-003',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-09T09:55:00',views:383,tags:['afwijkend advies','aflossingsvrij','vastleggen'],beste:'vbk-003-a2',
  titel:'Klant wil volledig aflossingsvrij terwijl ik dat niet passend vind',
  body:`Een stel van rond de vijftig wil de nieuwe hypotheek zoveel mogelijk aflossingsvrij houden om maandlasten laag te houden. Mijn advies is om (deels) af te lossen, omdat de lasten na pensionering anders te hoog worden. Zij houden vast aan hun keuze. Hoe leg ik dit netjes vast?`,
  antwoorden:[
   {id:'vbk-003-a1',auteur:'u8',datum:'2025-10-10T10:26:00',rA:{u1:5,u2:3,u6:3,u7:3},rAdv:{u3:3,u6:3},body:`Dit is een klassiek afwijkend-adviesdossier. Leg vast wat jouw advies was, waarom, en waarom de klant afwijkt.
- Benoem concreet het risico: welke lasten na pensioendatum en wat de restschuld is op die datum.
- Laat de klant schriftelijk bevestigen dat hij het advies heeft begrepen en bewust afwijkt.
- Controleer of het gekozen product binnen de acceptatievoorwaarden van de geldverstrekker past.
Let op: afwijken van je advies mag, maar je blijft verantwoordelijk voor de bemiddeling. Als de afwijkende keuze echt onverantwoord is, kun je ook besluiten niet te bemiddelen.`},
   {id:'vbk-003-a2',auteur:'u5',datum:'2025-10-10T21:30:00',rA:{u2:4,u4:3},rAdv:{u2:3,u3:4,u4:4,u7:5},body:`Ik werk in zo'n geval altijd met een berekening naast elkaar: mijn advies en de keuze van de klant, met de lasten na pensioendatum. Die bijlage gaat mee in het dossier. Vaak kiest de klant dan toch voor een tussenvorm, bijvoorbeeld een deel annuitair. Geef de klant ook mee dat hij later extra kan aflossen, maar check de boetevrije ruimte in de voorwaarden.`},
   {id:'vbk-003-a3',auteur:'u2',datum:'2025-10-11T04:39:00',rA:{},rAdv:{u6:5,u8:4},body:`Bespreek ook welk vermogen of pensioen er straks wel is. Soms is aflossingsvrij te onderbouwen als er elders voldoende vermogen staat, maar dan moet dat concreet in het dossier staan en niet als aanname.`}
  ]},
 {id:'vbk-004',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-14T20:30:00',views:165,tags:['dienstverleningsdocument','informatieverstrekking'],beste:'vbk-004-a1',
  titel:'Hoe vaak moet het dienstverleningsdocument worden bijgewerkt?',
  body:`Ons dienstverleningsdocument is al een paar jaar oud. De tarieven zijn intussen aangepast en we bieden ook een nieuw abonnement aan. Is er een vaste termijn voor actualisatie?`,
  antwoorden:[
   {id:'vbk-004-a1',auteur:'u8',datum:'2025-10-15T14:19:00',rA:{u6:5,u7:3},rAdv:{u4:3,u6:3},body:`Er is geen vaste termijn, maar het document moet kloppen op het moment dat je het aan de klant geeft. Gewijzigde tarieven, diensten of beloningsvormen betekenen dus direct een nieuwe versie. Zet een versiedatum op het document en bewaar per klant welke versie is verstrekt. Neem het actualiseren op in je jaarlijkse compliance-check, zodat je het niet vergeet.`}
  ]},
 {id:'vbk-005',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-17T21:10:00',views:183,tags:['PE','vakbekwaamheid','Wft'],beste:null,
  titel:'PE-deadline gemist door ziekte: wat zijn de gevolgen?',
  body:`Een collega heeft door langdurige ziekte zijn PE-examens niet op tijd gehaald. Mag hij nog adviseren zolang hij herstelt en de examens inhaalt? Wat moet het kantoor nu doen?`,
  antwoorden:[
   {id:'vbk-005-a1',auteur:'u8',datum:'2025-10-18T09:25:00',rA:{u5:3,u6:5,u7:5},rAdv:{u2:3,u3:3,u4:5,u5:5},body:`Zonder actuele vakbekwaamheid mag iemand niet zelfstandig adviseren op dat domein. Laat hem tot hij de PE-examens heeft gehaald niet zelfstandig adviseren of tekenen, en laat een vakbekwame collega de adviezen doen of controleren. Leg in je vakbekwaamheidsadministratie vast wat er is gebeurd en welke maatregel je hebt genomen. Kijk voor de precieze regels en eventuele uitzonderingen bij het CDFD en de actuele regelgeving, en documenteer die afweging.`}
  ]},
 {id:'vbk-006',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-21T09:45:00',views:323,tags:['risicoprofiel','vermogensopbouw','klantprofiel'],beste:'vbk-006-a1',
  titel:'Risicobereidheid vastleggen bij vermogensopbouw naast de hypotheek',
  body:`Een klant wil naast zijn hypotheek gaan beleggen om later af te lossen. Hoe uitgebreid moet ik de risicobereidheid uitvragen, en wat als zijn antwoorden elkaar tegenspreken?`,
  antwoorden:[
   {id:'vbk-006-a1',auteur:'u2',datum:'2025-10-21T19:09:00',rA:{u1:4,u4:4,u5:4,u8:5},rAdv:{u4:4,u7:3},body:`Gebruik een vragenlijst die kennis en ervaring, financiële positie, doelstelling en risicobereidheid apart meet. Tegenstrijdige antwoorden moet je in het gesprek uitdiepen, niet laten staan. Vraag bijvoorbeeld wat hij doet als zijn belegging een flink deel daalt vlak voor het aflosmoment. Leg vast welk profiel je uiteindelijk hanteert en waarom, en hoe je de tegenstrijdigheid hebt opgelost.`},
   {id:'vbk-006-a2',auteur:'u8',datum:'2025-10-22T06:07:00',rA:{u3:3,u6:4},rAdv:{u3:5,u6:4},body:`Vermeld in het dossier ook dat je de klant hebt gewezen op het risico dat het doelvermogen niet wordt gehaald. Als je zelf geen beleggingsadvies mag geven, check dan of je vergunning dit dekt voordat je hierover adviseert.`}
  ]},
 {id:'vbk-007',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-23T20:25:00',views:565,tags:['ORV','afwijkend advies','overlijden'],beste:'vbk-007-a2',
  titel:'Klant weigert overlijdensrisicoverzekering: wat leg ik vast?',
  body:`Ik adviseer een ORV omdat de achterblijvende partner de lasten anders niet kan dragen. De klant wil die kosten niet maken en accepteert het risico. Hoe ver moet ik gaan in het overtuigen, en wat zet ik in het dossier?`,
  antwoorden:[
   {id:'vbk-007-a1',auteur:'u3',datum:'2025-10-24T09:13:00',rA:{u2:4,u4:4,u5:3},rAdv:{u2:5,u7:4},body:`Overtuigen hoeft niet, informeren wel. Laat met een berekening zien wat er gebeurt met de woonlasten als een van beiden overlijdt, en bespreek ook het nabestaandenpensioen en eventuele andere voorzieningen. Daarna vastleggen dat de klant het risico begrijpt en bewust afziet van de ORV. Laat beide partners tekenen, want het raakt vooral de achterblijver.`},
   {id:'vbk-007-a2',auteur:'u5',datum:'2025-10-24T18:36:00',rA:{u1:5,u2:4,u3:3,u4:4},rAdv:{},body:`Check ook of de geldverstrekker een ORV als voorwaarde stelt, bijvoorbeeld bij een hoge financiering ten opzichte van de woningwaarde. Dan is weigeren geen optie en moet je dat de klant direct duidelijk maken.`}
  ]},
 {id:'vbk-008',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-28T16:40:00',views:551,tags:['kennis en ervaring','klantprofiel','dossier'],beste:null,
  titel:'Vragenlijst kennis en ervaring: is een standaardformulier genoeg?',
  body:`We laten klanten vooraf een online vragenlijst invullen over kennis en ervaring met financiële producten. Is dat voldoende, of moet ik dit ook in het gesprek toetsen?`,
  antwoorden:[
   {id:'vbk-008-a1',auteur:'u8',datum:'2025-10-29T11:21:00',rA:{u1:5,u4:4,u6:3},rAdv:{},body:`Een vragenlijst is een prima startpunt, maar je moet zelf beoordelen of de antwoorden kloppen. Klanten schatten hun kennis vaak te hoog in. Toets in het gesprek een paar kernbegrippen, zoals rentevaste periode of het verschil tussen annuitair en lineair. Leg vast welke onderdelen je hebt toegelicht en of de klant ze begreep.`},
   {id:'vbk-008-a2',auteur:'u1',datum:'2025-10-30T03:19:00',rA:{u3:5,u5:3},rAdv:{u6:4},body:`Bij ons staat in de gespreksnotitie een korte zin per product: wat de klant al wist en wat ik heb uitgelegd. Dat kost weinig tijd en het dossier wordt er veel sterker van.`}
  ]},
 {id:'vbk-009',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-01T12:05:00',views:497,tags:['provisieverbod','beloning','bestaande polis'],beste:'vbk-009-a1',
  titel:'Doorlopende provisie op oude polissen: mag dat nog?',
  body:`Ik heb een portefeuille overgenomen met oude levensverzekeringen waarop nog doorlopende provisie wordt betaald. Mag ik die blijven ontvangen? En verandert dat als ik de klant opnieuw adviseer?`,
  antwoorden:[
   {id:'vbk-009-a1',auteur:'u8',datum:'2025-11-01T20:38:00',rA:{u5:4,u6:4},rAdv:{u3:4,u4:5,u6:3},body:`Het provisieverbod geldt voor complexe producten en verzekeringen waarbij de klant een financieel belang heeft, voor zover ze zijn afgesloten na de invoering van het verbod. Bij oudere polissen kan doorlopende provisie onder voorwaarden blijven bestaan. Pas op bij wijzigingen: als de polis zodanig wordt aangepast dat het juridisch een nieuw product is, gelden de nieuwe regels. Check de voorwaarden in de overnameovereenkomst en vraag bij twijfel de verzekeraar wat er bij een wijziging gebeurt. Leg vast welke beloning je ontvangt en informeer de klant daarover.`},
   {id:'vbk-009-a2',auteur:'u3',datum:'2025-11-02T10:09:00',rA:{u4:5,u6:4,u7:5},rAdv:{u1:4},body:`In de praktijk vraag ik bij elke wijziging aan zo'n oude polis eerst bij de verzekeraar na wat dat met de provisiestroom doet. Daarna spreek ik met de klant een fee af voor het nieuwe advies, zodat er geen dubbele beloning ontstaat.`}
  ]},
 {id:'vbk-010',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-05T14:15:00',views:282,tags:['opdrachtbevestiging','fee','kostentransparantie'],beste:'vbk-010-a1',
  titel:'Opdrachtbevestiging bij adviesfee: welke onderdelen zijn verplicht?',
  body:`We werken met vaste fees voor hypotheekadvies. Een klant stopte halverwege en betwist nu de factuur. Wat moet er minimaal in een opdrachtbevestiging staan om dit te voorkomen?`,
  antwoorden:[
   {id:'vbk-010-a1',auteur:'u8',datum:'2025-11-06T04:53:00',rA:{u2:5},rAdv:{u3:4,u6:3},body:`Zorg dat de klant voor de start weet wat hij krijgt en wat het kost. Neem op:
- welke diensten onder de fee vallen en welke niet;
- het bedrag of de berekening van de fee;
- wat er gebeurt bij tussentijds stoppen of als de financiering niet doorgaat;
- het moment van facturering.
Laat de klant tekenen voordat je inhoudelijk begint. Als dat ontbreekt, sta je bij een geschil zwak.`},
   {id:'vbk-010-a2',auteur:'u4',datum:'2025-11-06T22:41:00',rA:{u1:5,u3:3,u6:5,u7:3},rAdv:{u1:5,u5:3,u7:5},body:`Wij werken met een fasering: oriëntatie, advies, bemiddeling, elk met een eigen deelbedrag. Stopt de klant na de adviesfase, dan factureren we alleen dat deel. Dat voorkomt veel discussie.`},
   {id:'vbk-010-a3',auteur:'u1',datum:'2025-11-07T16:14:00',rA:{u4:4,u7:3,u8:5},rAdv:{},body:`Stuur bij twijfel eerst een vriendelijk overzicht van de uitgevoerde werkzaamheden met de gesprekken en stukken erbij. Vaak is de discussie dan snel voorbij.`}
  ]},
 {id:'vbk-011',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-08T13:05:00',views:76,tags:['identificatie','videobellen','Wwft'],beste:null,
  titel:'Identificatie van een klant die we alleen via video spreken',
  body:`Steeds meer klanten willen het hele traject digitaal doen, zonder bezoek aan kantoor. Hoe stellen we de identiteit vast als we iemand alleen via een videogesprek zien?`,
  antwoorden:[
   {id:'vbk-011-a1',auteur:'u8',datum:'2025-11-08T21:23:00',rA:{u3:4,u5:4,u7:5},rAdv:{u7:5},body:`Een kopie van het identiteitsbewijs bekijken in een videogesprek is niet hetzelfde als een fysieke controle. Gebruik bij voorkeur een betrouwbare digitale identificatiemethode via een erkende leverancier. Leg vast welke methode je gebruikte, wanneer, en wie de controle deed. Voor de hypotheekaanvraag zelf stelt de geldverstrekker ook eisen aan identificatie; controleer die voorwaarden, want de notaris identificeert sowieso fysiek bij het passeren.`},
   {id:'vbk-011-a2',auteur:'u6',datum:'2025-11-09T14:57:00',rA:{u7:4},rAdv:{u1:4,u2:4,u4:5},body:`In ons adviespakket kun je de uitkomst van de digitale ID-check als document aan het klantdossier koppelen. Zet er een korte notitie bij met de methode en de datum, dan is het later direct terug te vinden.`}
  ]},
 {id:'vbk-012',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-12T08:55:00',views:398,tags:['partner','inventarisatie','informatieplicht'],beste:'vbk-012-a1',
  titel:'Een van de partners komt nooit bij het adviesgesprek',
  body:`Bij een gezamenlijke hypotheek zie ik alleen de man; de vrouw heeft geen tijd voor de gesprekken. Zij wordt wel medeschuldenaar. Kan ik zo verantwoord adviseren?`,
  antwoorden:[
   {id:'vbk-012-a1',auteur:'u5',datum:'2025-11-13T06:54:00',rA:{u2:4,u3:3,u7:4},rAdv:{u2:4,u6:4,u8:4},body:`Nee, niet zonder haar betrokkenheid. Zij wordt hoofdelijk aansprakelijk voor de hele schuld en haar risicos (inkomen, pensioen, arbeidsongeschiktheid) moet je zelf met haar bespreken. Plan minimaal een gesprek, eventueel via video, waarin je haar situatie en wensen uitvraagt en de risicos toelicht. Leg vast dat ze het advies heeft ontvangen en begrijpt.`},
   {id:'vbk-012-a2',auteur:'u8',datum:'2025-11-13T21:49:00',rA:{u1:3,u3:5,u7:5},rAdv:{u2:4,u3:3,u4:3,u6:4},body:`Laat haar het klantprofiel en het advies zelf bevestigen. Een handtekening die de partner meeneemt, zegt niets over of zij de inhoud heeft begrepen. Bij een klacht is juist die tweede partij vaak de klager.`}
  ]},
 {id:'vbk-013',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-15T19:35:00',views:231,tags:['pensioen','betaalbaarheid','hypotheek'],beste:'vbk-013-a1',
  titel:'Pensioeninkomen meenemen in hypotheekadvies voor dertigers',
  body:`Moet ik bij klanten van rond de dertig echt al het pensioeninkomen meenemen in de toets of de lasten later betaalbaar blijven? Dat is nog zo ver weg en onzeker.`,
  antwoorden:[
   {id:'vbk-013-a1',auteur:'u7',datum:'2025-11-15T22:13:00',rA:{u1:3,u2:4,u6:3,u8:4},rAdv:{u4:5},body:`Ja, als de hypotheek doorloopt na de pensioendatum moet je inzichtelijk maken wat er dan gebeurt. Gebruik het actuele pensioenoverzicht van de klant en vermeld dat het een indicatie is. Kijk of er aflossing plaatsvindt voor de pensioendatum; dan is het risico vaak beperkt. Leg vast wat je hebt besproken en welke gegevens je gebruikte.`},
   {id:'vbk-013-a2',auteur:'u1',datum:'2025-11-16T03:23:00',rA:{u2:3,u4:4,u5:4},rAdv:{u2:5,u3:3,u7:3},body:`Ik laat de klant zijn overzicht uit het pensioenregister ophalen en zet het in het dossier. Bij jonge klanten is de boodschap meestal kort: met een annuitaire lening is de schuld afgelost voor de pensioendatum. Bij aflossingsvrije delen wordt het gesprek uitgebreider.`},
   {id:'vbk-013-a3',auteur:'u2',datum:'2025-11-16T07:20:00',rA:{u3:3,u4:5,u5:4},rAdv:{u1:3,u5:5,u8:4},body:`Bespreek ook de AOW-leeftijd, want die verschuift mee met de levensverwachting. Werk met de actuele gegevens en noem de onzekerheid expliciet.`}
  ]},
 {id:'vbk-014',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-19T10:20:00',views:341,tags:['oversluiten','rentemiddeling','motivatie'],beste:null,
  titel:'Oversluiten of rentemiddeling: hoe onderbouw ik de keuze in het dossier?',
  body:`Een klant vraagt of hij moet oversluiten of rentemiddelen. Ik heb beide doorgerekend. Welke onderdelen moeten zeker in de motivatie staan zodat de keuze later te volgen is?`,
  antwoorden:[
   {id:'vbk-014-a1',auteur:'u4',datum:'2025-11-20T06:57:00',rA:{u1:3,u2:5,u3:5,u8:3},rAdv:{u1:3,u5:4,u6:4,u7:3},body:`Zet de varianten naast elkaar over dezelfde periode:
- maandlasten en totale rentekosten;
- boeterente of opslag bij middeling, plus overige kosten (advies, notaris, taxatie);
- het break-even moment;
- de verwachting van de klant over verhuizen of verbouwen.
Vermeld de datum van de gebruikte rentes, want die veranderen snel.`},
   {id:'vbk-014-a2',auteur:'u8',datum:'2025-11-20T13:16:00',rA:{u3:4,u6:4},rAdv:{u1:3,u5:5,u6:4,u7:3},body:`Leg ook de onzekerheid vast: een vergelijking is een momentopname. Als de klant de voorkeur heeft voor zekerheid boven de laagste kosten, schrijf dat letterlijk op. Daarmee is ook later te volgen waarom de goedkoopste variant niet is gekozen.`}
  ]},
 {id:'vbk-015',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-21T07:05:00',views:237,tags:['arbeidsongeschiktheid','woonlasten','afwijkend advies'],beste:'vbk-015-a1',
  titel:'Klant wil geen arbeidsongeschiktheidsdekking voor de woonlasten',
  body:`Uit de berekening blijkt een fors tekort bij arbeidsongeschiktheid. De klant werkt in loondienst en zegt dat de werkgever het wel regelt. Wat moet ik nu aantonen in mijn dossier?`,
  antwoorden:[
   {id:'vbk-015-a1',auteur:'u3',datum:'2025-11-22T05:43:00',rA:{u2:3},rAdv:{u1:4,u4:4,u7:5},body:`Laat met de actuele gegevens zien wat de klant ontvangt in de verschillende fasen: loondoorbetaling, eventuele WGA-uitkering en de aanvullende regelingen van de werkgever. Vraag het arbeidsvoorwaardenreglement of de polis van de werkgever op; aannames zijn onvoldoende. Blijft er een tekort, dan leg je vast dat de klant bewust afziet van aanvullende dekking.`},
   {id:'vbk-015-a2',auteur:'u7',datum:'2025-11-22T12:55:00',rA:{u1:3,u3:3,u4:3,u5:5},rAdv:{u2:4,u4:5,u5:3,u6:5},body:`Let op het verschil tussen een WGA-hiaatverzekering en een WIA-excedentverzekering bij de werkgever; klanten halen die vaak door elkaar. Een kopie van de regeling in het dossier voorkomt discussie.`}
  ]},
 {id:'vbk-016',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-26T14:25:00',views:382,tags:['adviesrapport','dossier','motivatie'],beste:null,
  titel:'Mag een adviesrapport kort zijn als het gesprek uitgebreid was?',
  body:`Onze adviesrapporten zijn erg lang en klanten lezen ze niet. Ik wil een kort rapport van een paar paginas met de kern. Is dat toegestaan als de onderbouwing in de gespreksverslagen staat?`,
  antwoorden:[
   {id:'vbk-016-a1',auteur:'u8',datum:'2025-11-27T12:48:00',rA:{u6:5},rAdv:{u1:3,u2:5,u5:5,u6:4},body:`Een kort rapport kan, zolang het advies en de motivatie voor de klant begrijpelijk zijn en de onderbouwing in het dossier herleidbaar is. Het gaat erom dat de klant kan zien waarom dit advies bij hem past. Verwijs in het rapport naar de bijlagen met de berekeningen. Zorg dat de klant ook die bijlagen ontvangt, niet alleen het korte stuk.`},
   {id:'vbk-016-a2',auteur:'u6',datum:'2025-11-27T13:52:00',rA:{u3:5},rAdv:{u1:4,u3:4,u7:3,u8:4},body:`In het adviespakket kun je de rapportopbouw per onderdeel aan- of uitzetten. Zet de berekeningen dan als bijlage en controleer na het genereren of de motivatieteksten echt meekomen.`}
  ]},
 {id:'vbk-017',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-29T08:25:00',views:469,tags:['overwaarde','consumptief','verhoging'],beste:null,
  titel:'Overwaarde opnemen voor een auto of reis: passend?',
  body:`Een klant wil overwaarde opnemen om een auto en een verre reis te betalen. De ruimte is er volgens de normen. Hoe kijken jullie hier tegenaan qua zorgplicht?`,
  antwoorden:[
   {id:'vbk-017-a1',auteur:'u5',datum:'2025-11-29T16:20:00',rA:{u6:5},rAdv:{u4:5,u7:3},body:`Dat iets past binnen de normen betekent nog niet dat het verstandig is. Bespreek dat de klant een kortlevend bezit financiert met een schuld die lang doorloopt, en reken uit wat dat over de looptijd kost. Vergelijk het met een korter lopend alternatief. Leg vast welke alternatieven je hebt besproken en waarom de klant toch voor deze route kiest.`},
   {id:'vbk-017-a2',auteur:'u4',datum:'2025-11-29T22:11:00',rA:{},rAdv:{u1:4,u2:5,u3:5,u6:4},body:`Check ook de voorwaarden van de geldverstrekker voor bestedingsdoelen. Niet elke verstrekker accepteert elk doel of elk aflossingsschema, en voor fiscale aftrek is de besteding natuurlijk ook bepalend.`}
  ]},
 {id:'vbk-018',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-04T16:45:00',views:291,tags:['motivatie','standaardteksten','AFM'],beste:'vbk-018-a1',
  titel:'Standaardteksten in de motivatie: gaat de AFM daarover vallen?',
  body:`Ons adviespakket heeft standaardteksten voor de motivatie die we vaak ongewijzigd overnemen. Een collega zegt dat dit bij een toets niet volstaat. Hoe ver moet je personaliseren?`,
  antwoorden:[
   {id:'vbk-018-a1',auteur:'u8',datum:'2025-12-05T07:51:00',rA:{},rAdv:{u1:4,u3:4,u4:4,u5:4},body:`De motivatie moet laten zien waarom het advies past bij deze klant. Standaardteksten zijn prima als bouwsteen, maar moeten worden aangevuld met de concrete situatie: inkomen, wensen, risicos en de gemaakte keuzes. Een test: als je de klantnaam weghaalt en de tekst past op elk dossier, is het te algemeen. Laat periodiek een collega een steekproef doen.`},
   {id:'vbk-018-a2',auteur:'u6',datum:'2025-12-06T02:13:00',rA:{u2:3,u4:4,u5:4,u8:4},rAdv:{u1:3,u2:3,u4:5,u5:3},body:`Je kunt in het adviespakket de standaardteksten zo inrichten dat ze een invulveld bevatten dat verplicht moet worden aangepast. Zo voorkom je dat ze ongemerkt ongewijzigd in het rapport belanden.`},
   {id:'vbk-018-a3',auteur:'u1',datum:'2025-12-06T08:53:00',rA:{u5:3,u6:3,u7:5},rAdv:{u4:5,u5:3,u6:3,u8:3},body:`Ik schrijf per risicoparagraaf een of twee eigen zinnen bovenop de standaardtekst. Dat is weinig werk en maakt het verschil.`}
  ]},
 {id:'vbk-019',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-07T20:00:00',views:410,tags:['zzp','inkomen','betaalbaarheid'],beste:null,
  titel:'Inkomen van een zzp-er met sterk wisselende jaren',
  body:`Een zelfstandige had twee goede jaren en een slecht jaar. De inkomensverklaring komt op een gemiddelde uit dat hoog genoeg is. Moet ik als adviseur ook zelf een oordeel geven over duurzaamheid van het inkomen?`,
  antwoorden:[
   {id:'vbk-019-a1',auteur:'u5',datum:'2025-12-07T21:10:00',rA:{u3:4},rAdv:{u4:3,u6:5,u7:5},body:`Ja. De inkomensbepaling volgt de normen, maar jouw zorgplicht gaat over de vraag of de lasten op lange termijn betaalbaar zijn. Bespreek met de klant wat er gebeurt als het slechte jaar zich herhaalt en of er een buffer is. Leg dat scenario en de reactie van de klant vast. Overweeg een lager bedrag te adviseren dan maximaal mogelijk.`}
  ]},
 {id:'vbk-020',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-09T14:35:00',views:339,tags:['senioren','verhoging','zorgplicht'],beste:'vbk-020-a1',
  titel:'Hypotheek verhogen voor een klant van boven de zeventig',
  body:`Een alleenstaande klant van ruim zeventig wil zijn woning aanpassen en daarvoor de hypotheek verhogen. Het pensioen is stabiel. Waar moet ik extra op letten bij deze doelgroep?`,
  antwoorden:[
   {id:'vbk-020-a1',auteur:'u5',datum:'2025-12-10T02:51:00',rA:{u4:5,u6:5,u7:4},rAdv:{u6:4,u7:5,u8:3},body:`Let op de lange termijn: wat gebeurt er bij verhuizing naar een zorginstelling, en wie erft de schuld? Bespreek of de klant kinderen wil betrekken, maar alleen met zijn toestemming. Controleer de leeftijdsvoorwaarden en de acceptatie van de geldverstrekker. Kijk ook of de klant het advies goed begrijpt; twijfel je daarover, leg vast hoe je dat hebt getoetst.`},
   {id:'vbk-020-a2',auteur:'u2',datum:'2025-12-10T10:55:00',rA:{u3:3,u4:4},rAdv:{u1:4,u4:3,u8:5},body:`Bekijk naast een verhoging ook alternatieven zoals een verzilverhypotheek of het inzetten van spaargeld. Leg vast welke alternatieven je hebt besproken.`},
   {id:'vbk-020-a3',auteur:'u8',datum:'2025-12-10T22:35:00',rA:{u1:3,u2:3,u4:5},rAdv:{u2:5},body:`Pas op met aannames over wilsbekwaamheid. Een aantekening als de klant begreep de uitleg en kon de hoofdlijnen in eigen woorden herhalen is waardevol in het dossier.`}
  ]},
 {id:'vbk-021',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-14T15:05:00',views:426,tags:['duurzaamheid','energielabel','adviesgesprek'],beste:null,
  titel:'Moet ik verduurzaming verplicht bespreken in een hypotheekadvies?',
  body:`Klanten vragen er niet altijd om, maar ik hoor verschillende geluiden over of verduurzaming standaard onderdeel moet zijn van het adviesgesprek. Hoe gaan jullie hiermee om?`,
  antwoorden:[
   {id:'vbk-021-a1',auteur:'u1',datum:'2025-12-15T07:25:00',rA:{u2:3,u4:5},rAdv:{u3:5,u6:3},body:`Ik bespreek het altijd kort: het energielabel, de financieringsruimte voor energiebesparende maatregelen en de invloed op woonlasten. Wil de klant er niets mee, dan noteer ik dat. Het kost twee minuten en je dossier is compleet.`},
   {id:'vbk-021-a2',auteur:'u8',datum:'2025-12-15T17:56:00',rA:{u1:5,u3:4,u4:3,u6:5},rAdv:{u1:4,u4:3,u5:4,u7:3},body:`Toets je werkwijze aan de leidraad en de actuele AFM-publicaties. Verduurzaming raakt de betaalbaarheid en de waarde van de woning, dus het past bij een volledige inventarisatie. Vermeld in het dossier wat besproken is en wat de klant besloot.`}
  ]},
 {id:'vbk-022',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-16T07:25:00',views:204,tags:['adviesrapport','ondertekening','dossier'],beste:'vbk-022-a1',
  titel:'Klant tekent het adviesrapport niet: kan ik toch bemiddelen?',
  body:`Een klant reageert niet op mijn verzoek om het adviesrapport te ondertekenen, maar wil wel dat ik de aanvraag doorzet. Is een handtekening verplicht?`,
  antwoorden:[
   {id:'vbk-022-a1',auteur:'u8',datum:'2025-12-16T20:17:00',rA:{u2:3,u3:3,u4:5},rAdv:{},body:`Een handtekening is niet in alle gevallen wettelijk verplicht, maar wel je beste bewijs dat de klant het advies heeft ontvangen en akkoord is. Zonder handtekening moet je op een andere manier aantonen dat de klant akkoord ging, bijvoorbeeld een bevestiging per e-mail. Stuur een korte samenvatting met het verzoek om schriftelijk akkoord en bewaar de reactie.`},
   {id:'vbk-022-a2',auteur:'u4',datum:'2025-12-17T09:13:00',rA:{u2:5,u3:5,u6:4},rAdv:{u2:4,u5:5,u7:4,u8:3},body:`Wij gebruiken digitaal ondertekenen, dat verlaagt de drempel enorm. Als de klant echt niet wil tekenen, zet ik dat in een notitie met de datum en de reden.`}
  ]},
 {id:'vbk-023',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-21T12:35:00',views:271,tags:['advies','informatie','afbakening'],beste:null,
  titel:'Wanneer is het informatie en wanneer is het advies?',
  body:`Aan de telefoon geef ik bestaande klanten vaak een korte reactie op een vraag, zoals of extra aflossen verstandig is. Wanneer is dat al advies in de zin van de Wft?`,
  antwoorden:[
   {id:'vbk-023-a1',auteur:'u8',datum:'2025-12-22T09:15:00',rA:{u3:5,u4:3,u6:5,u7:5},rAdv:{u3:4},body:`Zodra je een persoonlijke aanbeveling doet die is afgestemd op de situatie van de klant, is het advies. Algemene uitleg over hoe extra aflossen werkt is informatie; een aanbeveling dat deze klant het beter wel of niet kan doen is advies. Dan geldt je zorgplicht met inventarisatie en vastlegging. Train je medewerkers op dat onderscheid en noteer telefonische adviezen in het dossier.`}
  ]},
 {id:'vbk-024',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-24T07:15:00',views:82,tags:['overdracht','dossier','verantwoordelijkheid'],beste:null,
  titel:'Adviesdossier overnemen van een zieke collega',
  body:`Een collega is uitgevallen midden in een adviestraject. Ik neem het over, maar ik ken de klant niet en het dossier is incompleet. Wie is verantwoordelijk voor het advies dat ik afrond?`,
  antwoorden:[
   {id:'vbk-024-a1',auteur:'u4',datum:'2025-12-24T18:16:00',rA:{u1:4,u2:5,u3:5},rAdv:{},body:`Jij bent verantwoordelijk voor het advies dat jij uitbrengt. Ga dus niet blind af op het werk van je collega. Bel de klant, stel jezelf voor en loop het klantprofiel samen na. Vul aan wat ontbreekt en leg vast wat je hebt overgenomen en wat je opnieuw hebt getoetst.`}
  ]},
 {id:'vbk-025',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-27T11:10:00',views:90,tags:['klachten','Kifid','klachtenregeling'],beste:null,
  titel:'Termijn voor het afhandelen van een interne klacht',
  body:`We kregen een schriftelijke klacht over het advies van vorig jaar. Hoe snel moeten we reageren, en wat moeten we de klant meesturen over de vervolgstappen?`,
  antwoorden:[
   {id:'vbk-025-a1',auteur:'u8',datum:'2025-12-28T10:15:00',rA:{u1:5,u4:4,u5:4},rAdv:{u1:4,u3:4,u5:5},body:`Stuur direct een ontvangstbevestiging met de naam van de behandelaar en de verwachte termijn. Een consument kan bij Kifid terecht als jullie niet binnen acht weken een definitief standpunt hebben gegeven, of als hij het oneens is met dat standpunt. Richt je eigen proces daarom zo in dat je ruim binnen die acht weken afrondt.
- Laat de klacht behandelen door iemand die niet zelf het advies gaf.
- Vraag het dossier op en hoor de adviseur.
- Geef een schriftelijk, gemotiveerd standpunt.
- Noem in die brief expliciet dat de klant naar Kifid kan, met de termijn waarbinnen dat moet: drie maanden na jullie definitieve standpunt. Die termijn geldt alleen als je er in de brief op wijst; daarnaast kan de klant in elk geval binnen een jaar na het indienen van de klacht bij jullie naar Kifid. Controleer de actuele termijnen in het reglement van Kifid.
Registreer de klacht in de klachtenregistratie, inclusief datum van binnenkomst, standpunt en eventuele verbetermaatregel.`}
  ]},
 {id:'vbk-026',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-05T20:00:00',views:98,tags:['Wwft','UBO','cliëntenonderzoek'],beste:'vbk-026-a1',
  titel:'UBO vaststellen bij een klant met een holding',
  body:`Een DGA wil via zijn holding een hypotheek op een beleggingspand. De structuur heeft twee lagen met een stichting ertussen. Hoe ver moet ik gaan om de uiteindelijk belanghebbende vast te stellen?`,
  antwoorden:[
   {id:'vbk-026-a1',auteur:'u8',datum:'2026-01-05T23:53:00',rA:{u2:5,u7:5},rAdv:{u3:3,u5:5},body:`Je moet de UBO vaststellen en redelijke maatregelen nemen om die identiteit te verifiëren, dus ook door de tussenliggende lagen heen. Een uittreksel uit het UBO-register is een hulpmiddel, maar je mag niet uitsluitend daarop vertrouwen. Vraag een organogram van de structuur op en de statuten van de stichting. Leg vast:
- hoe de zeggenschap en het eigendom lopen;
- welke bronnen je hebt gebruikt;
- wie je uiteindelijk als UBO aanmerkt en waarom.
Kom je er niet uit, dan is dat op zich al een signaal om het cliëntenonderzoek te verzwaren.`},
   {id:'vbk-026-a2',auteur:'u2',datum:'2026-01-06T02:06:00',rA:{u3:5,u5:5,u6:4,u7:5},rAdv:{u1:3,u4:4,u6:4},body:`Praktische tip: laat de accountant van de klant een korte verklaring geven over de structuur. Dat versnelt het traject en je hebt meteen een onderbouwing in het dossier.`}
  ]},
 {id:'vbk-027',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-09T21:30:00',views:438,tags:['Wwft','PEP','verscherpt onderzoek'],beste:'vbk-027-a1',
  titel:'Klant is politiek prominent persoon: wat moet ik extra doen?',
  body:`Uit de PEP-check blijkt dat een nieuwe klant lid is van een provinciaal bestuur. Hij wil een hypotheek van een fors bedrag. Welke extra stappen zijn nodig voordat we het advies mogen uitbrengen?`,
  antwoorden:[
   {id:'vbk-027-a1',auteur:'u8',datum:'2026-01-10T16:26:00',rA:{u5:3},rAdv:{u2:3},body:`Bij een PEP geldt verscherpt cliëntenonderzoek. Je moet onder meer de bron van het vermogen en van de middelen vaststellen, en het aangaan van de relatie moet worden goedgekeurd door iemand op leidinggevend niveau binnen je kantoor. Daarnaast houd je de relatie doorlopend verscherpt in de gaten. Controleer in je Wwft-beleid welke functies jullie als PEP aanmerken en wie de goedkeuring geeft. Leg de goedkeuring met datum en naam van de functionaris vast in het dossier.`},
   {id:'vbk-027-a2',auteur:'u5',datum:'2026-01-10T23:27:00',rA:{u2:5,u8:5},rAdv:{u6:5,u7:3},body:`Vraag bij de eigen inbreng gewoon bankafschriften op waaruit de herkomst blijkt. Dat doe je bij elke klant al, maar bij een PEP documenteer je het extra zorgvuldig.`}
  ]},
 {id:'vbk-028',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-12T14:30:00',views:542,tags:['Wwft','melden','FIU'],beste:'vbk-028-a1',
  titel:'Ongebruikelijke transactie: mag ik de klant vertellen dat ik meld?',
  body:`Een klant brengt een groot bedrag aan contant geld in als eigen middelen en kan de herkomst niet goed uitleggen. Ik twijfel of ik moet melden. Als ik meld, mag ik dat dan aan de klant laten weten?`,
  antwoorden:[
   {id:'vbk-028-a1',auteur:'u8',datum:'2026-01-13T03:55:00',rA:{u2:4,u3:5,u4:5,u7:4},rAdv:{u2:5,u3:5,u4:4,u6:5},body:`Nee, je mag de klant niet informeren dat je een melding doet of hebt gedaan; dat is het tipping-off verbod. Toets de transactie aan de indicatoren uit de regelgeving en aan jullie eigen beleid, en meld bij twijfel aan de FIU-Nederland. De meldplicht geldt ook als de transactie uiteindelijk niet doorgaat. Leg intern vast welke overweging je hebt gemaakt en bewaar dat gescheiden van het gewone klantdossier.`},
   {id:'vbk-028-a2',auteur:'u4',datum:'2026-01-13T20:26:00',rA:{u3:5,u6:4,u7:4},rAdv:{u3:5},body:`Bespreek het vooraf altijd met je compliance officer of Wwft-functionaris. Je hoeft deze afweging niet alleen te maken en een tweede paar ogen voorkomt fouten.`},
   {id:'vbk-028-a3',auteur:'u1',datum:'2026-01-14T03:06:00',rA:{u4:5,u5:5,u6:5,u8:5},rAdv:{u5:4,u6:5,u7:3,u8:4},body:`En weiger niet impulsief aan de telefoon. Zeg dat je de stukken intern beoordeelt, dan voorkom je dat je per ongeluk iets prijsgeeft.`}
  ]},
 {id:'vbk-029',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-14T21:50:00',views:82,tags:['Wwft','bewaartermijn','dossier'],beste:'vbk-029-a1',
  titel:'Hoe lang moeten we Wwft-gegevens bewaren?',
  body:`We willen ons archief opschonen. Hoe lang moeten we kopieën van identiteitsbewijzen en de gegevens van het cliëntenonderzoek bewaren na het einde van de klantrelatie?`,
  antwoorden:[
   {id:'vbk-029-a1',auteur:'u8',datum:'2026-01-15T10:29:00',rA:{},rAdv:{u6:3},body:`De Wwft schrijft voor dat je deze gegevens vijf jaar bewaart na het beëindigen van de zakelijke relatie of na het uitvoeren van de transactie. Daarna moet je ze in beginsel vernietigen, want de AVG staat langer bewaren zonder grondslag niet toe. Let op: voor het adviesdossier zelf kunnen andere termijnen gelden, bijvoorbeeld in verband met mogelijke klachten. Leg je bewaartermijnen per soort gegeven vast in een bewaarbeleid.`},
   {id:'vbk-029-a2',auteur:'u6',datum:'2026-01-15T13:29:00',rA:{u1:5,u2:3,u3:5,u7:3},rAdv:{u2:3,u8:4},body:`In het CRM kun je vaak een einddatum relatie vastleggen en daar een opschoontaak aan koppelen. Dan wordt het niet vergeten.`}
  ]},
 {id:'vbk-030',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-19T19:00:00',views:63,tags:['AVG','BSN','identificatie'],beste:'vbk-030-a1',
  titel:'Kopie paspoort met BSN in het dossier: mag dat?',
  body:`Wij bewaren standaard een volledige kopie van het paspoort. Een collega zegt dat we het BSN moeten afschermen. Wie heeft gelijk?`,
  antwoorden:[
   {id:'vbk-030-a1',auteur:'u8',datum:'2026-01-20T08:22:00',rA:{u2:5,u7:3},rAdv:{},body:`Het mag alleen als je daar een wettelijke grondslag voor hebt. Voor de Wwft-identificatie mag je een kopie bewaren, en bij de hypotheekaanvraag heeft de geldverstrekker het BSN vaak nodig. Heb je het BSN voor jouw doel niet nodig, dan scherm je het af, net als de pasfoto als die niet nodig is. Leg in je privacybeleid vast welke gegevens je voor welk doel bewaart.`},
   {id:'vbk-030-a2',auteur:'u1',datum:'2026-01-20T13:17:00',rA:{},rAdv:{},body:`Wij laten klanten de kopie aanleveren via een beveiligde portal en niet per gewone e-mail. Dat scheelt ook een hoop discussie bij een audit.`}
  ]},
 {id:'vbk-031',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-20T21:00:00',views:387,tags:['AVG','datalek','melden'],beste:'vbk-031-a1',
  titel:'Datalek: adviesrapport naar het verkeerde e-mailadres gestuurd',
  body:`Een collega heeft een volledig adviesrapport met inkomensgegevens naar een verkeerde ontvanger gemaild. De ontvanger reageert niet. Moeten we dit melden?`,
  antwoorden:[
   {id:'vbk-031-a1',auteur:'u8',datum:'2026-01-21T06:43:00',rA:{u7:3},rAdv:{u5:5},body:`Dit is een datalek. Je moet het melden bij de Autoriteit Persoonsgegevens binnen 72 uur nadat je het ontdekt, tenzij het waarschijnlijk geen risico oplevert. Bij financiële gegevens is dat risico er bijna altijd. Is het risico hoog, dan informeer je ook de betrokken klant. Registreer elk datalek in je interne register, ook als je niet meldt, met de afweging die je maakte.`},
   {id:'vbk-031-a2',auteur:'u3',datum:'2026-01-21T07:46:00',rA:{u1:3,u2:3,u6:3},rAdv:{u6:5,u7:5},body:`Probeer de ontvanger wel te bereiken met het verzoek het bericht te verwijderen en dat te bevestigen. Dat helpt bij de risico-inschatting.`},
   {id:'vbk-031-a3',auteur:'u6',datum:'2026-01-21T12:37:00',rA:{u3:3,u4:4},rAdv:{u1:4,u5:4,u8:5},body:`Zet een vertraging op uitgaande mail of gebruik een beveiligde mailoplossing. Dan kun je zo iets nog terughalen.`}
  ]},
 {id:'vbk-032',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-25T14:15:00',views:100,tags:['AVG','inzage','dossier'],beste:'vbk-032-a1',
  titel:'Klant vraagt inzage in zijn hele dossier',
  body:`Een oud-klant met wie we een meningsverschil hebben vraagt om een kopie van alle gegevens die we over hem hebben, inclusief interne notities. Moeten we ook die notities geven?`,
  antwoorden:[
   {id:'vbk-032-a1',auteur:'u8',datum:'2026-01-26T02:02:00',rA:{},rAdv:{},body:`Het inzagerecht ziet op alle persoonsgegevens die je over de klant verwerkt, en daaronder vallen in beginsel ook interne notities over hem. Je hoeft geen interne overwegingen te geven die niet over de klant gaan, en de rechten van anderen mag je afschermen. Reageer binnen een maand. Leg vast wanneer het verzoek binnenkwam en wat je hebt verstrekt.`},
   {id:'vbk-032-a2',auteur:'u2',datum:'2026-01-26T18:19:00',rA:{u6:5},rAdv:{u4:3,u5:4,u6:4},body:`Lees bij een lopend meningsverschil de notities eerst kritisch door. Het is een goede reminder om feitelijk te noteren en geen meningen over de klant in het dossier te zetten.`}
  ]},
 {id:'vbk-033',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-28T13:50:00',views:23,tags:['afwijkend advies','rentevast','vastlegging'],beste:'vbk-033-a1',
  titel:'Afwijkend advies: klant kiest een kortere rentevaste periode',
  body:`Ik adviseer twintig jaar rentevast vanwege de krappe maandlasten, maar de klant kiest vijf jaar voor de lagere rente. Kan ik dit gewoon bemiddelen?`,
  antwoorden:[
   {id:'vbk-033-a1',auteur:'u5',datum:'2026-01-29T09:52:00',rA:{u7:3},rAdv:{u1:3,u2:3},body:`Dat kan, maar dan is het een afwijking van je advies en dat moet helder in het dossier staan. Laat zien dat je de risico's concreet hebt gemaakt, bijvoorbeeld met een berekening van de maandlast bij een hogere rente na vijf jaar. De klant bevestigt schriftelijk dat hij bewust afwijkt en de gevolgen kent. Controleer ook of de gekozen variant binnen de acceptatiecriteria van de geldverstrekker past.`},
   {id:'vbk-033-a2',auteur:'u8',datum:'2026-01-29T14:08:00',rA:{u2:5,u5:3,u6:3},rAdv:{u6:4},body:`Belangrijk: het moet een eigen keuze van de klant zijn en geen voorstel van jou dat je achteraf als afwijking labelt. Een keuze die leidt tot een niet-verantwoorde situatie moet je overigens niet willen bemiddelen.`},
   {id:'vbk-033-a3',auteur:'u4',datum:'2026-01-29T17:38:00',rA:{u1:3,u6:5},rAdv:{u3:4,u5:5,u7:3,u8:3},body:`Ik maak een aparte paragraaf afwijkingen van het advies in het rapport, zo is het voor de klant ook echt zichtbaar.`}
  ]},
 {id:'vbk-034',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-30T13:10:00',views:118,tags:['afwijkend advies','zorgplicht','weigeren'],beste:null,
  titel:'Wanneer moet ik weigeren te bemiddelen na een afwijkende keuze?',
  body:`Een klant wil een maximale hypotheek en geen enkele voorziening voor overlijden, terwijl de partner dan de woning niet kan houden. Wanneer is een afwijkende keuze zo onverstandig dat ik niet meer moet meewerken?`,
  antwoorden:[
   {id:'vbk-034-a1',auteur:'u8',datum:'2026-01-31T07:38:00',rA:{},rAdv:{u1:3},body:`Er is geen harde grens, maar de zorgplicht houdt niet op bij een handtekening van de klant. Als de keuze leidt tot een situatie die duidelijk niet verantwoord is, mag je ook besluiten niet te bemiddelen. Leg in je kantoorbeleid vast welke afwijkingen je wel accepteert en welke niet, dan is het niet afhankelijk van de individuele adviseur. Bespreek twijfelgevallen met een collega en leg die afweging vast.`},
   {id:'vbk-034-a2',auteur:'u1',datum:'2026-01-31T09:18:00',rA:{u8:3},rAdv:{},body:`Ik laat bij zulke klanten de partner apart reageren op de scenarioberekening. Vaak kiest het stel dan toch voor een basisdekking.`}
  ]},
 {id:'vbk-035',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-03T15:50:00',views:480,tags:['klantprofiel','inventarisatie','dossier'],beste:'vbk-035-a1',
  titel:'Moet de klant het klantprofiel zelf invullen?',
  body:`Wij laten klanten een online vragenlijst invullen en gebruiken die als klantprofiel. Is dat voldoende, of moet ik in het gesprek alles nog eens doorlopen?`,
  antwoorden:[
   {id:'vbk-035-a1',auteur:'u5',datum:'2026-02-04T08:19:00',rA:{u6:4,u7:3},rAdv:{u7:4},body:`Een online vragenlijst is een goed begin, maar jij moet de informatie beoordelen en waar nodig doorvragen. Klanten vullen doelen en risicobereidheid vaak anders in dan ze in het gesprek vertellen. Noteer in het dossier welke antwoorden je hebt besproken en wat je hebt aangepast. Zo laat je zien dat het profiel echt van de klant is en door jou is getoetst.`},
   {id:'vbk-035-a2',auteur:'u6',datum:'2026-02-04T23:50:00',rA:{u1:4,u5:5,u7:5,u8:3},rAdv:{},body:`In de meeste adviespakketten kun je zien welke velden de klant zelf invulde en welke de adviseur wijzigde. Handig bij een dossiercontrole.`}
  ]},
 {id:'vbk-036',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-08T14:25:00',views:24,tags:['Kifid','klachten','beleid'],beste:null,
  titel:'Kifid-uitspraak verloren: moet ik het intern melden?',
  body:`Een klachtprocedure bij het Kifid is in het nadeel van ons kantoor uitgevallen. Moet ik dit ergens melden, en wat doen we er intern mee?`,
  antwoorden:[
   {id:'vbk-036-a1',auteur:'u8',datum:'2026-02-09T09:08:00',rA:{},rAdv:{u3:3,u5:5,u6:4,u7:3},body:`Controleer in je eigen beleid en bij je beroepsaansprakelijkheidsverzekeraar of en wanneer je een claim of uitspraak moet melden; vaak moet dat al bij de eerste aansprakelijkstelling. Intern is het vooral een leermoment. Analyseer wat er misging, pas zo nodig werkwijze of templates aan en leg de evaluatie vast. Bij een terugkerend patroon hoort het ook in je risicoanalyse.`}
  ]},
 {id:'vbk-037',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-10T10:50:00',views:21,tags:['Kifid','klachten','procedure'],beste:'vbk-037-a1',
  titel:'Klant wil de klacht direct bij het Kifid indienen',
  body:`Een klant dreigt meteen naar het Kifid te stappen zonder eerst bij ons te klagen. Kan dat zomaar?`,
  antwoorden:[
   {id:'vbk-037-a1',auteur:'u8',datum:'2026-02-11T03:14:00',rA:{},rAdv:{u4:3,u6:5,u7:5},body:`Het Kifid verwacht dat de klant eerst een klacht bij de financiële dienstverlener indient en de interne procedure doorloopt. Pas als die niet tot een oplossing leidt, of als je niet tijdig reageert, kan de klant naar het Kifid. Wijs de klant op jullie klachtenregeling en neem de klacht direct serieus in behandeling. Zet in je reactie altijd de mogelijkheid van het Kifid en de termijn die daarvoor geldt.`},
   {id:'vbk-037-a2',auteur:'u2',datum:'2026-02-11T06:45:00',rA:{},rAdv:{u1:4,u4:5},body:`Bel de klant eerst. Heel vaak gaat het om een misverstand dat je in een gesprek oplost, voordat het een formele procedure wordt.`}
  ]},
 {id:'vbk-038',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-13T19:35:00',views:201,tags:['passend advies','betaalbaarheid','leennormen'],beste:'vbk-038-a1',
  titel:'Adviesrapport bij een betaalbaarheid op het randje',
  body:`De maximale hypotheek volgens de leennormen past net, maar het vrij besteedbaar inkomen na de woonlasten is volgens mijn eigen budgetanalyse erg krap. Mag ik toch de maximale hypotheek adviseren?`,
  antwoorden:[
   {id:'vbk-038-a1',auteur:'u5',datum:'2026-02-14T00:32:00',rA:{u2:4,u3:4,u4:3,u7:4},rAdv:{},body:`De leennormen geven een maximum, geen advies. Jouw zorgplicht vraagt dat je beoordeelt of de lasten ook voor deze klant verantwoord zijn, op basis van zijn werkelijke uitgavenpatroon. Als je budgetanalyse laat zien dat het krap is, adviseer je een lager bedrag of leg je uit waarom je het toch verantwoord vindt. Leg die afweging en de budgetberekening vast in het dossier.`},
   {id:'vbk-038-a2',auteur:'u1',datum:'2026-02-14T05:43:00',rA:{},rAdv:{u3:5,u4:3,u5:3,u8:5},body:`Ik bespreek dan de uitgaven met de klant en laat zien wat er overblijft per maand. Klanten kiezen dan zelf vaak voor minder.`}
  ]},
 {id:'vbk-039',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-19T19:00:00',views:514,tags:['interne controle','kwaliteit','dossier'],beste:'vbk-039-a1',
  titel:'Toetsing van de adviseur zelf: wie controleert mijn dossiers?',
  body:`Ik ben eenpitter en er is niemand die mijn dossiers controleert. Wat is een realistische manier om toch kwaliteitscontrole in te bouwen?`,
  antwoorden:[
   {id:'vbk-039-a1',auteur:'u8',datum:'2026-02-20T05:55:00',rA:{u2:4,u4:4},rAdv:{u4:4,u5:5,u6:4},body:`Veel zelfstandigen sluiten een afspraak met een collega-adviseur of een externe compliance-dienstverlener voor periodieke dossiercontroles. Kies een vast aantal dossiers per periode, bijvoorbeeld steekproefsgewijs, en gebruik een vaste checklist. Leg de bevindingen en verbeterpunten vast, en kijk de volgende keer of ze zijn opgepakt. Zo kun je laten zien dat je kwaliteit structureel bewaakt.`},
   {id:'vbk-039-a2',auteur:'u4',datum:'2026-02-20T20:23:00',rA:{u2:4},rAdv:{u1:5,u3:5,u5:5,u6:3},body:`Wij doen dit met drie zelfstandige kantoren onderling. Werkt goed, en je leert ook veel van elkaars werkwijze.`}
  ]},
 {id:'vbk-040',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-20T09:40:00',views:155,tags:['beloningsbeleid','integriteit','Wft'],beste:'vbk-040-a1',
  titel:'Beloning op basis van productie: risico voor passend advies?',
  body:`Ons kantoor wil een bonus invoeren voor adviseurs op basis van het aantal afgesloten hypotheken. Kan dat zonder problemen met de regelgeving?`,
  antwoorden:[
   {id:'vbk-040-a1',auteur:'u8',datum:'2026-02-21T00:53:00',rA:{},rAdv:{},body:`Hier moet je voorzichtig zijn. Beloningsbeleid mag geen prikkels geven die het belang van de klant schaden. Een bonus puur op aantallen of volume kan zo werken. Laat beoordelingen meewegen die over kwaliteit gaan, zoals dossierkwaliteit en klanttevredenheid. Controleer de actuele regels voor variabele beloning en leg het beloningsbeleid en de afweging schriftelijk vast.`}
  ]},
 {id:'vbk-041',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-26T17:50:00',views:43,tags:['dossier','opname','AVG'],beste:null,
  titel:'Vastleggen van een adviesgesprek met opname',
  body:`Ik zou adviesgesprekken willen opnemen als bewijs van wat er besproken is. Mag dat en wat moet ik regelen?`,
  antwoorden:[
   {id:'vbk-041-a1',auteur:'u8',datum:'2026-02-26T23:13:00',rA:{u2:5,u4:5},rAdv:{u2:5,u4:4},body:`Opnemen kan, maar het is een verwerking van persoonsgegevens. Informeer de klant vooraf, leg het doel vast en zorg voor een grondslag. Bepaal hoe lang je de opnames bewaart en wie er toegang toe heeft. Een opname vervangt de schriftelijke vastlegging in het dossier niet, het is hooguit aanvullend.`},
   {id:'vbk-041-a2',auteur:'u6',datum:'2026-02-27T04:02:00',rA:{u5:4},rAdv:{},body:`Let ook op waar de opnames worden opgeslagen. Gebruik een omgeving waarvoor je een verwerkersovereenkomst hebt.`},
   {id:'vbk-041-a3',auteur:'u1',datum:'2026-02-27T16:15:00',rA:{u3:3,u4:3,u6:4,u7:5},rAdv:{u5:4},body:`Ik vond de korte gespreksnotitie met akkoord van de klant uiteindelijk praktischer dan opnames terugluisteren.`}
  ]},
 {id:'vbk-042',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-01T16:55:00',views:153,tags:['AVG','verwerker','software'],beste:'vbk-042-a1',
  titel:'Verwerkersovereenkomst met het adviespakket nodig?',
  body:`We gebruiken een online adviespakket en een CRM in de cloud. Moeten we daar een verwerkersovereenkomst mee hebben?`,
  antwoorden:[
   {id:'vbk-042-a1',auteur:'u6',datum:'2026-03-02T09:50:00',rA:{u1:4,u5:5,u7:3},rAdv:{u1:4,u4:4,u5:4},body:`Ja, als de leverancier namens jou persoonsgegevens verwerkt, is een verwerkersovereenkomst verplicht. De meeste leveranciers hebben een standaardovereenkomst die je in de klantomgeving kunt accepteren of opvragen. Controleer waar de gegevens worden opgeslagen, welke beveiliging er is en welke subverwerkers worden ingezet. Bewaar de getekende overeenkomst bij je privacydocumentatie.`},
   {id:'vbk-042-a2',auteur:'u8',datum:'2026-03-03T00:54:00',rA:{u3:5,u5:5,u7:5},rAdv:{},body:`Neem de leveranciers ook op in je verwerkingsregister. Dat is het eerste wat gevraagd wordt bij een controle.`}
  ]},
 {id:'vbk-043',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-05T20:55:00',views:235,tags:['nazorg','zorgplicht','dossier'],beste:null,
  titel:'Is een zorgplichtbrief na het afsluiten nog nodig?',
  body:`Na het passeren sturen wij geen brief meer. Een collega-kantoor stuurt een afsluitende brief met uitleg over rentevaste periodes en wanneer de klant zich moet melden. Is dat verplicht?`,
  antwoorden:[
   {id:'vbk-043-a1',auteur:'u8',datum:'2026-03-06T09:30:00',rA:{u1:4,u4:4,u5:5},rAdv:{u1:4,u5:4},body:`Er is geen wettelijk voorgeschreven afsluitende brief, maar je zorgplicht eindigt niet bij de passeerdatum. Uit je vergelijkingskaart (die sinds april 2023 het dienstverleningsdocument vervangt) en je opdrachtbevestiging blijkt welke nazorg je belooft; die moet je dan ook waarmaken. De herziene Leidraad Hypotheekadvisering van de AFM (april 2026) vraagt om duidelijke afspraken over de omvang van de nazorg en de vergoeding daarvoor. Een afsluitende brief is een eenvoudige manier om dat aan te tonen.
Wat ik erin zou zetten:
- Een samenvatting van de afgesloten producten en de einddatum van de rentevaste periodes.
- Wanneer de klant zich moet melden: bij wijziging van inkomen, relatie, gezinssituatie of verhuizing.
- Of jullie de klant actief benaderen bij renteherziening, of dat de klant dat zelf moet doen.
Bewaar een kopie in het dossier. Doen jullie aan abonnementsnazorg, dan is de brief eigenlijk onmisbaar. Zie ook nazorg-check.html.`}
  ]},
 {id:'vbk-044',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-08T10:30:00',views:396,tags:['vergunning','Wft','vakbekwaamheid'],beste:'vbk-044-a1',
  titel:'Erkenning voor schadeverzekeringen en hypotheken tegelijk',
  body:`We willen naast hypotheken ook schadeverzekeringen gaan adviseren. Wat moeten we regelen voordat we daarmee starten?`,
  antwoorden:[
   {id:'vbk-044-a1',auteur:'u3',datum:'2026-03-08T11:53:00',rA:{u5:5,u6:4},rAdv:{u8:3},body:`Controleer eerst of jullie vergunning bij de AFM de juiste productcategorieën omvat. Zo niet, dan moet je die uitbreiden voordat je adviseert. Daarnaast moeten de adviseurs die gaan adviseren de juiste diploma's hebben en hun PE bijhouden. Pas ook je dienstverleningsdocument en je beroepsaansprakelijkheidsverzekering aan.`},
   {id:'vbk-044-a2',auteur:'u8',datum:'2026-03-08T13:28:00',rA:{u2:5,u5:4,u6:3},rAdv:{},body:`Vergeet het productaanbod niet: leg vast met welke verzekeraars je werkt en hoe je selecteert. Dat hoort ook in je informatie aan de klant.`}
  ]},
 {id:'vbk-045',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-11T15:15:00',views:285,tags:['integriteit','fraude','dossier'],beste:'vbk-045-a1',
  titel:'Hoe gaan jullie om met een klant die liegt over zijn inkomen?',
  body:`Bij een controle van de stukken blijkt dat een werkgeversverklaring niet klopt met de salarisstroken. De klant zegt dat het een fout van de werkgever is. Hoe ga ik hiermee om?`,
  antwoorden:[
   {id:'vbk-045-a1',auteur:'u4',datum:'2026-03-12T12:15:00',rA:{u2:3,u5:5,u6:5,u8:4},rAdv:{u3:3,u6:4,u7:5},body:`Ga niet zelf de stukken aanpassen of verklaren. Vraag de klant om een gecorrigeerde verklaring rechtstreeks via de werkgever en controleer die met de salarisstroken en eventueel een UWV-verzekeringsbericht. Komt er geen goede verklaring, dan bemiddel je de aanvraag niet. Leg vast wat je hebt geconstateerd en welke vervolgstappen je hebt gezet.`},
   {id:'vbk-045-a2',auteur:'u8',datum:'2026-03-12T20:14:00',rA:{},rAdv:{u1:5,u4:5},body:`Bij signalen van fraude moet je ook kijken naar je meldplicht onder de Wwft en het incidentenbeleid van je kantoor. Bespreek het met je compliance officer.`},
   {id:'vbk-045-a3',auteur:'u5',datum:'2026-03-12T23:28:00',rA:{u3:4,u4:5,u7:4,u8:3},rAdv:{},body:`Een aanvraag met onjuiste gegevens doorzetten is ook voor jou als adviseur een groot risico. Wees daar zakelijk en duidelijk over richting de klant.`}
  ]},
 {id:'vbk-046',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-15T12:10:00',views:419,tags:['dossier','AVG','beveiliging'],beste:'vbk-046-a1',
  titel:'Dossierstukken in de mailbox van de adviseur',
  body:`Bij ons staan veel klantstukken alleen in de mailbox van de adviseur. Als iemand vertrekt, zijn we die kwijt. Hoe richten jullie dit in?`,
  antwoorden:[
   {id:'vbk-046-a1',auteur:'u6',datum:'2026-03-15T21:52:00',rA:{u1:3},rAdv:{u3:3,u4:3,u8:4},body:`Sla alle relevante stukken op in het CRM of dossiersysteem, gekoppeld aan de klant. Veel pakketten kunnen e-mails met bijlagen direct opslaan in het dossier. Maak er een vaste werkafspraak van en controleer het bij dossiercontroles. Persoonlijke mailboxen zijn geen archief.`},
   {id:'vbk-046-a2',auteur:'u8',datum:'2026-03-16T17:53:00',rA:{u1:5,u3:4,u7:5},rAdv:{u2:4,u3:5,u6:3},body:`Stel ook vast hoe lang mail in mailboxen bewaard blijft. Gegevens verspreid over mailboxen zijn lastig te verwijderen als de bewaartermijn verloopt.`}
  ]},
 {id:'vbk-047',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-18T15:55:00',views:314,tags:['advies','geldverstrekker','actualiteit'],beste:null,
  titel:'Productvoorwaarden van de geldverstrekker veranderen na het advies',
  body:`Tussen het advies en de offerte zijn de acceptatievoorwaarden van de geldverstrekker veranderd. Het advies past nog, maar de onderbouwing klopt niet meer helemaal. Moet ik het rapport aanpassen?`,
  antwoorden:[
   {id:'vbk-047-a1',auteur:'u1',datum:'2026-03-18T19:32:00',rA:{u4:4,u8:4},rAdv:{u7:4,u8:5},body:`Ja, het dossier moet aansluiten bij wat er daadwerkelijk is afgesloten. Pas de onderbouwing aan of maak een korte addendum met wat er is veranderd en waarom het advies nog passend is. Laat de klant dat addendum bevestigen. Controleer ook of de wijziging gevolgen heeft voor de maandlasten of de voorwaarden.`}
  ]},
 {id:'vbk-048',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-22T08:40:00',views:220,tags:['klachten','registratie','beleid'],beste:null,
  titel:'Interne klachtenregistratie: wat moet erin?',
  body:`We willen een eenvoudige klachtenregistratie opzetten. Welke gegevens leggen jullie per klacht vast?`,
  antwoorden:[
   {id:'vbk-048-a1',auteur:'u8',datum:'2026-03-23T08:10:00',rA:{u1:4,u5:4,u6:5},rAdv:{u4:4,u6:4},body:`Houd het eenvoudig maar volledig, zodat je trends ziet en bij een AFM- of Kifid-vraag direct kunt laten zien hoe je klachten behandelt. Per klacht registreren wij:
- Datum ontvangst, kanaal en klantnummer (geen overbodige persoonsgegevens).
- Product en dienst, betrokken adviseur en onderwerp van de klacht.
- Behandelaar, datum ontvangstbevestiging en datum definitief standpunt.
- Uitkomst: gegrond, ongegrond of deels, en eventuele compensatie.
- Of de klant naar Kifid is gegaan.
- Oorzaak en verbetermaatregel.
Bespreek de registratie periodiek met de directie en leg dat vast. Zet de registratie in een systeem met beperkte toegang; denk aan de AVG-bewaartermijnen.`}
  ]},
 {id:'vbk-049',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-25T15:10:00',views:521,tags:['overbrugging','dossier','risico'],beste:'vbk-049-a1',
  titel:'Hoe leg ik advies over een overbruggingskrediet vast?',
  body:`Bij een doorstromer adviseer ik een overbruggingskrediet. Welke risico's moet ik minimaal bespreken en vastleggen?`,
  antwoorden:[
   {id:'vbk-049-a1',auteur:'u5',datum:'2026-03-25T19:12:00',rA:{u1:4,u2:5},rAdv:{u6:4},body:`Bespreek wat er gebeurt als de oude woning later of voor minder wordt verkocht dan verwacht, en of de klant de dubbele lasten kan dragen. Onderbouw de waarde van de oude woning met een taxatie of een realistische inschatting. Leg vast:
- hoe je de verwachte verkoopopbrengst hebt bepaald;
- de looptijd en voorwaarden van het overbruggingskrediet;
- het scenario met dubbele lasten en hoe lang de klant dat kan opvangen.
Controleer de voorwaarden van de geldverstrekker voor de maximale looptijd.`},
   {id:'vbk-049-a2',auteur:'u4',datum:'2026-03-25T22:17:00',rA:{},rAdv:{},body:`Ik reken altijd een scenario door met een lagere verkoopprijs. Klanten zijn vaak te optimistisch over hun oude woning.`}
  ]},
 {id:'vbk-050',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-29T19:30:00',views:378,tags:['AVG','doelbinding','familie'],beste:'vbk-050-a1',
  titel:'Gegevens van een eerdere klant hergebruiken voor familie',
  body:`De zoon van een bestaande klant komt voor een hypotheek en vraagt of ik de gegevens van zijn ouders gebruik voor een schenking. Mag ik die gegevens zomaar inzien en gebruiken?`,
  antwoorden:[
   {id:'vbk-050-a1',auteur:'u8',datum:'2026-03-30T03:47:00',rA:{u1:4,u3:4},rAdv:{u2:4,u4:4},body:`Nee, de gegevens van de ouders zijn verstrekt voor hun eigen advies. Voor een ander doel mag je ze niet zomaar gebruiken. Vraag de ouders om toestemming of laat ze de benodigde informatie opnieuw aanleveren voor dit traject. Leg die toestemming vast.`},
   {id:'vbk-050-a2',auteur:'u2',datum:'2026-03-30T20:31:00',rA:{u7:4},rAdv:{u4:4},body:`In de praktijk vraag ik de ouders gewoon om een schenkingsverklaring en een bankafschrift. Dan heb je precies wat je nodig hebt.`}
  ]},
 {id:'vbk-051',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-02T15:10:00',views:383,tags:['pensioen','zorgplicht','hypotheek'],beste:'vbk-051-a1',
  titel:'Pensioenadvies bij een hypotheek: hoe ver gaat mijn zorgplicht?',
  body:`Ik adviseer een stel van midden vijftig over een nieuwe hypotheek die doorloopt tot na de AOW-leeftijd. Moet ik hun pensioensituatie volledig in kaart brengen of volstaat een globale inschatting?`,
  antwoorden:[
   {id:'vbk-051-a1',auteur:'u7',datum:'2026-04-03T12:46:00',rA:{u1:5,u5:3,u6:4},rAdv:{u2:3,u5:5},body:`Als de hypotheek doorloopt na de pensioendatum moet je onderbouwen dat de lasten dan ook betaalbaar zijn. Daarvoor heb je een betrouwbaar beeld nodig van het te verwachten pensioeninkomen, bijvoorbeeld via een actueel pensioenoverzicht van alle uitvoerders. Een globale inschatting zonder bron is lastig te verdedigen. Leg vast welke gegevens je hebt gebruikt en hoe je met onzekerheden omgaat.`},
   {id:'vbk-051-a2',auteur:'u5',datum:'2026-04-04T05:49:00',rA:{u4:5,u6:3,u7:3,u8:5},rAdv:{u8:5},body:`Toets ook de situatie bij overlijden van een van beiden na pensionering. Het nabestaandenpensioen valt vaak lager uit dan klanten denken.`},
   {id:'vbk-051-a3',auteur:'u8',datum:'2026-04-04T20:07:00',rA:{},rAdv:{},body:`Controleer de acceptatievoorwaarden van de geldverstrekker voor leningen die doorlopen na de pensioendatum, die verschillen per partij.`}
  ]},
 {id:'vbk-052',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-06T16:00:00',views:313,tags:['inventarisatie','weigering','dossier'],beste:'vbk-052-a1',
  titel:'Klant wil geen financiële informatie over zijn spaargeld geven',
  body:`Een klant wil geen inzicht geven in zijn spaargeld en beleggingen, omdat hij vindt dat dat niets met de hypotheek te maken heeft. Kan ik dan nog adviseren?`,
  antwoorden:[
   {id:'vbk-052-a1',auteur:'u5',datum:'2026-04-06T18:03:00',rA:{u4:5,u6:4},rAdv:{u4:4,u6:3,u7:4},body:`Leg uit waarom je het vraagt: vermogen bepaalt bijvoorbeeld of extra inbreng of aflossen verstandig is en of hij risico's zelf kan opvangen. Weigert hij toch, dan kun je in beperkte mate adviseren, maar dat moet je in je advies benoemen en vastleggen. Ontbreekt informatie die essentieel is voor het advies, dan kun je ook besluiten niet te adviseren. Zorg dat de klant ziet welke gevolgen het weglaten heeft.`},
   {id:'vbk-052-a2',auteur:'u2',datum:'2026-04-06T22:22:00',rA:{},rAdv:{u5:3},body:`Vaak helpt het te vragen naar een orde van grootte in plaats van exacte bedragen. Dan heb je in elk geval iets om op te bouwen.`}
  ]},
 {id:'vbk-053',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-10T17:30:00',views:313,tags:['actualiteit','dossier','herziening'],beste:'vbk-053-a1',
  titel:'Adviesrapport na een jaar nog geldig?',
  body:`Een klant kreeg vorig jaar advies maar kocht toen geen woning. Nu heeft hij wel een woning gevonden. Kan ik het oude rapport gebruiken?`,
  antwoorden:[
   {id:'vbk-053-a1',auteur:'u1',datum:'2026-04-11T08:52:00',rA:{u4:5,u5:5,u6:4,u8:5},rAdv:{u4:5},body:`Nee, niet zonder actualisatie. Inkomen, rente, voorwaarden en wensen kunnen allemaal veranderd zijn. Doorloop het klantprofiel opnieuw met de klant, werk berekeningen bij en maak een nieuw of aangevuld advies. Leg vast wat je hebt gecontroleerd en wat er is gewijzigd.`},
   {id:'vbk-053-a2',auteur:'u4',datum:'2026-04-11T10:50:00',rA:{u6:5,u7:3},rAdv:{u6:5,u8:3},body:`Bij ons is de vuistregel dat alles ouder dan een paar maanden opnieuw getoetst wordt. Het meeste kun je hergebruiken, maar de toets moet opnieuw.`}
  ]},
 {id:'vbk-054',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-15T10:50:00',views:592,tags:['integriteit','cadeaus','beleid'],beste:'vbk-054-a1',
  titel:'Hoe ga ik om met cadeaus van klanten?',
  body:`Na een afgerond traject krijg ik soms een fles wijn of een cadeaubon. Mag ik dat aannemen?`,
  antwoorden:[
   {id:'vbk-054-a1',auteur:'u8',datum:'2026-04-15T20:56:00',rA:{u1:4,u7:5},rAdv:{u1:4,u3:3,u7:3},body:`Kleine attenties zijn meestal geen probleem, maar leg in je integriteitsbeleid vast tot welke waarde iets acceptabel is en wanneer je het moet melden. Wees terughoudender met geschenken van productaanbieders, die kunnen je onafhankelijkheid raken. Registreer ontvangen geschenken boven de grens in een register. Bij twijfel weiger je beleefd.`}
  ]},
 {id:'vbk-055',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-17T19:30:00',views:126,tags:['kwetsbare klant','ouderen','zorgplicht'],beste:'vbk-055-a1',
  titel:'Ouderen en wilsbekwaamheid bij een adviesgesprek',
  body:`Een oudere klant lijkt in het gesprek niet alles goed te begrijpen. Een kind wil namens hem tekenen. Hoe ga ik hier zorgvuldig mee om?`,
  antwoorden:[
   {id:'vbk-055-a1',auteur:'u5',datum:'2026-04-17T22:00:00',rA:{u1:5,u3:4,u4:5,u6:3},rAdv:{},body:`Ga na of er een volmacht of levenstestament is en bekijk wat die precies toestaat. Een kind mag niet zomaar tekenen zonder bevoegdheid. Neem meer tijd, gebruik eenvoudige taal en controleer of de klant de kern begrijpt, bijvoorbeeld door hem het advies in eigen woorden te laten herhalen. Leg je waarnemingen en de getroffen maatregelen vast.`},
   {id:'vbk-055-a2',auteur:'u8',datum:'2026-04-18T09:34:00',rA:{},rAdv:{},body:`Twijfel je echt aan de wilsbekwaamheid, schakel dan de notaris in en adviseer niet voordat dat duidelijk is.`},
   {id:'vbk-055-a3',auteur:'u2',datum:'2026-04-18T14:15:00',rA:{u1:4,u3:5,u5:4,u6:3},rAdv:{},body:`Ik nodig in zulke gevallen altijd een vertrouwenspersoon uit bij het gesprek, met akkoord van de klant.`}
  ]},
 {id:'vbk-056',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-23T12:25:00',views:373,tags:['kwetsbare klant','beleid','zorgplicht'],beste:null,
  titel:'Wat is een kwetsbare klant en hoe herken ik die?',
  body:`In audits wordt steeds vaker gevraagd hoe we omgaan met kwetsbare klanten. Hebben jullie een definitie of signalenlijst?`,
  antwoorden:[
   {id:'vbk-056-a1',auteur:'u8',datum:'2026-04-23T18:08:00',rA:{u4:4,u5:5,u7:5},rAdv:{u1:4,u3:5,u5:5,u6:5},body:`Kwetsbaarheid is vaak tijdelijk en situatiegebonden: denk aan scheiding, ziekte, overlijden van een partner, geldzorgen of beperkte digitale of taalvaardigheid. Maak een korte signalenlijst en bespreek die met je team. Leg vast welke aanpassingen je kunt doen, zoals extra gespreksmomenten of eenvoudiger documenten. Noteer in het dossier wat je hebt gesignaleerd en wat je ermee deed.`},
   {id:'vbk-056-a2',auteur:'u3',datum:'2026-04-24T03:14:00',rA:{u4:5,u5:4},rAdv:{u1:3,u4:4,u5:5,u8:5},body:`Bij schadeverzekeringen zien we het vooral na een schade. Dan is extra uitleg over de afhandeling echt waardevol.`}
  ]},
 {id:'vbk-057',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-26T07:50:00',views:345,tags:['second opinion','advies','aansprakelijkheid'],beste:'vbk-057-a1',
  titel:'Klant vraagt om een tweede mening over het advies van een ander kantoor',
  body:`Iemand komt met een adviesrapport van een ander kantoor en vraagt of het goed is. Wat leg ik vast als ik daar een mening over geef?`,
  antwoorden:[
   {id:'vbk-057-a1',auteur:'u2',datum:'2026-04-27T00:44:00',rA:{u4:5,u7:5},rAdv:{u5:3,u7:5},body:`Spreek vooraf af wat de opdracht is: een beoordeling van het rapport of een eigen advies. Leg dat vast in een opdrachtbevestiging. Voor een oordeel over de passendheid heb je in feite dezelfde informatie nodig als voor een eigen advies. Geef je alleen een beperkte toets, benoem dan duidelijk wat je niet hebt beoordeeld.`},
   {id:'vbk-057-a2',auteur:'u8',datum:'2026-04-27T03:48:00',rA:{},rAdv:{u3:4,u6:4},body:`Wees zakelijk in je bevindingen over het werk van de collega. Je weet niet altijd wat er in het gesprek is besproken.`}
  ]},
 {id:'vbk-058',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-29T12:10:00',views:377,tags:['dossier','verantwoordelijkheid','samenwerking'],beste:'vbk-058-a1',
  titel:'Twee adviseurs in één dossier: wie tekent?',
  body:`Bij ons doet een junior de inventarisatie en tekent een senior het advies. De junior heeft nog niet alle diploma's. Is dat een probleem?`,
  antwoorden:[
   {id:'vbk-058-a1',auteur:'u8',datum:'2026-04-29T19:29:00',rA:{u3:5,u7:4},rAdv:{u4:3,u7:3},body:`Iemand zonder de vereiste vakbekwaamheid mag onder voorwaarden werkzaamheden doen onder verantwoordelijkheid van een vakbekwame adviseur. Controleer de actuele regels voor werken onder begeleiding en zorg dat die begeleiding aantoonbaar is. Het advies wordt gegeven en ondertekend door de vakbekwame adviseur. Leg in het dossier vast wie welk deel deed en dat de senior de inventarisatie heeft beoordeeld.`}
  ]},
 {id:'vbk-059',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-04T17:55:00',views:139,tags:['fraude','inkomen','controle'],beste:'vbk-059-a1',
  titel:'Hoe controleer ik een werkgeversverklaring op echtheid?',
  body:`We krijgen steeds vaker werkgeversverklaringen die er professioneel uitzien maar waar we aan twijfelen. Welke controles doen jullie standaard?`,
  antwoorden:[
   {id:'vbk-059-a1',auteur:'u4',datum:'2026-05-05T05:29:00',rA:{u2:4,u3:3,u7:5,u8:4},rAdv:{},body:`Vergelijk de verklaring met de salarisstroken en, als je die hebt, met een bankafschrift van de salarisbetaling. Controleer de gegevens van de werkgever in het Handelsregister en bel bij twijfel het algemene nummer van de werkgever, niet het nummer op de verklaring. Een UWV-verzekeringsbericht geeft ook een goed beeld. Leg vast welke controles je hebt gedaan.`},
   {id:'vbk-059-a2',auteur:'u1',datum:'2026-05-05T09:57:00',rA:{u3:3,u4:3,u5:4,u8:5},rAdv:{u6:4},body:`Veel geldverstrekkers accepteren tegenwoordig ook inkomensbepaling via digitale bronnen. Dat verkleint het fraude-risico flink.`}
  ]},
 {id:'vbk-060',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-06T19:05:00',views:39,tags:['SIRA','risicoanalyse','beleid'],beste:null,
  titel:'Moeten we elk jaar een systematische integriteitsrisicoanalyse doen?',
  body:`De AFM vraagt in een uitvraag naar onze integriteitsrisicoanalyse. Ons document is van een paar jaar geleden. Hoe vaak moet je die bijwerken?`,
  antwoorden:[
   {id:'vbk-060-a1',auteur:'u8',datum:'2026-05-07T14:09:00',rA:{u3:5},rAdv:{u7:4},body:`Je moet de analyse actueel houden. Dat betekent bijwerken bij relevante veranderingen, zoals nieuwe diensten, nieuwe klantgroepen of incidenten, en in elk geval periodiek evalueren. Een document dat jaren niet is aangeraakt, past daar niet bij. Leg bij iedere evaluatie vast wat je hebt bekeken en welke maatregelen zijn aangepast, ook als er weinig verandert.`}
  ]},
 {id:'vbk-061',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-10T20:50:00',views:92,tags:['buitenland','Wwft','identificatie'],beste:null,
  titel:'Adviseren aan een klant die in het buitenland woont',
  body:`Een expat die nog in het buitenland woont wil een woning in Nederland kopen. Wat moet ik extra regelen voor identificatie en het cliëntenonderzoek?`,
  antwoorden:[
   {id:'vbk-061-a1',auteur:'u8',datum:'2026-05-11T14:20:00',rA:{u1:4,u4:5,u5:4},rAdv:{u1:5,u4:4},body:`Op afstand mag, maar je moet de identiteit net zo betrouwbaar vaststellen als bij een fysiek gesprek. Let op de afbakening: het wettelijke Wwft-cliëntenonderzoek geldt voor Wwft-instellingen, zoals bemiddelaars in levensverzekeringen. Bemiddel je alleen in de hypotheek, dan doen de geldverstrekker en de notaris dat onderzoek; zorgvuldige identificatie blijft dan wel nodig voor je eigen zorgplicht en om fraude te voorkomen.
- Gebruik een betrouwbare digitale identificatie, of laat een kopie legitimeren via een notaris of ambassade. Combineer dat met een videogesprek waarin de klant zijn document toont.
- Leg het buitenlandse woonadres vast met een recent bewijsstuk.
- Check PEP- en sanctielijsten en vraag gericht naar de herkomst van het eigen geld, zeker bij buitenlandse rekeningen.
- Controleer of de geldverstrekker niet-ingezetenen accepteert en welk inkomen hij dan meetelt.
- Ga na of je kantoor dienstverlening aan deze klant in zijn woonland mag verlenen; dat verschilt per land.
Leg vast hoe je identiteit en herkomst van middelen hebt vastgesteld. Verwijs voor de fiscale kant (binnenlands of buitenlands belastingplichtig) naar een fiscalist.`}
  ]},
 {id:'vbk-062',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-15T12:45:00',views:137,tags:['adviesfee','opdrachtbevestiging','geschil'],beste:'vbk-062-a1',
  titel:'Klant wil de adviesfee na afloop niet betalen',
  body:`Het traject is afgerond, maar de klant weigert de fee te betalen omdat hij vindt dat het advies te weinig opleverde. Wat kan ik doen?`,
  antwoorden:[
   {id:'vbk-062-a1',auteur:'u2',datum:'2026-05-16T04:07:00',rA:{u4:4,u6:4},rAdv:{u4:4,u5:3,u6:4},body:`Kijk eerst wat er in de opdrachtbevestiging staat over de fee en het moment van betaling. Als die duidelijk was en getekend, sta je sterk. Ga in gesprek over de onvrede, want dat kan ook een klacht zijn die je moet behandelen volgens je klachtenregeling. Leg het verloop van het contact vast.`},
   {id:'vbk-062-a2',auteur:'u8',datum:'2026-05-16T10:26:00',rA:{u1:4},rAdv:{u2:3,u4:5,u5:4,u7:5},body:`Behandel het als klacht als de klant aangeeft ontevreden te zijn over de dienstverlening. Dat voorkomt dat het later bij het Kifid alsnog anders uitpakt.`}
  ]},
 {id:'vbk-063',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-18T11:40:00',views:354,tags:['bedenktijd','advies','klantbelang'],beste:null,
  titel:'Hoeveel tijd moet een klant krijgen om het advies te overwegen?',
  body:`Een klant wil het advies en de aanvraag in één gesprek afronden omdat hij snel wil kopen. Is dat verantwoord?`,
  antwoorden:[
   {id:'vbk-063-a1',auteur:'u8',datum:'2026-05-19T09:00:00',rA:{u1:4,u4:4,u5:5},rAdv:{u1:4,u5:5},body:`Er is geen vaste wettelijke bedenktijd tussen advies en aanvraag. Wel moet het advies passend zijn en moet de klant het begrijpen. De bedenktijd na het bindend aanbod van de geldverstrekker blijft bovendien gewoon gelden: minimaal veertien dagen, waarin de geldverstrekker het aanbod niet mag intrekken of in het nadeel van de klant mag wijzigen. De klant kan wel eerder tekenen. Controleer de actuele regels bij afm.nl.
Snel afronden kan dus, onder voorwaarden:
- Inventarisatie en analyse moeten volledig zijn, niet ingekort vanwege tijdsdruk.
- Bespreek de belangrijkste risico's expliciet en laat de klant het advies in eigen woorden samenvatten.
- Leg vast dat de klant zelf om spoed vroeg en waarom.
- Bied aan om onduidelijkheden na het gesprek nog te bespreken voordat het aanbod wordt getekend.
Twijfel je of de klant het overziet, plan dan een kort vervolggesprek. Haast is geen argument bij een klacht.`}
  ]},
 {id:'vbk-064',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-22T20:05:00',views:298,tags:['AOV','woonlasten','passend advies'],beste:'vbk-064-a1',
  titel:'Advies over een woonlastenverzekering naast een AOV',
  body:`Een zelfstandige heeft al een AOV. Moet ik in het hypotheekadvies dan nog een woonlastenverzekering bespreken?`,
  antwoorden:[
   {id:'vbk-064-a1',auteur:'u3',datum:'2026-05-23T01:10:00',rA:{u1:3},rAdv:{u1:3,u2:4,u5:5,u6:3},body:`Je moet het risico van arbeidsongeschiktheid in relatie tot de woonlasten bespreken. Kijk of de bestaande AOV voldoende uitkeert om de woonlasten en overige uitgaven te dragen, rekening houdend met de wachttijd en de dekking. Is dat zo, dan is een extra woonlastenverzekering mogelijk niet nodig. Leg vast welke polis je hebt beoordeeld en wat je conclusie is.`},
   {id:'vbk-064-a2',auteur:'u5',datum:'2026-05-23T08:01:00',rA:{u1:3,u2:5,u3:3,u4:4},rAdv:{u3:5},body:`Vraag de polisvoorwaarden op en lees ze echt. Het verschil tussen beroeps- en passende-arbeidsongeschiktheid maakt veel uit.`}
  ]},
 {id:'vbk-065',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-25T19:00:00',views:365,tags:['Wwft','schenking','herkomst'],beste:'vbk-065-a1',
  titel:'Wwft-verplichtingen bij een schenking van familie in het buitenland',
  body:`Een klant krijgt een schenking van familie uit het buitenland voor de eigen inbreng. Wat moet ik controleren?`,
  antwoorden:[
   {id:'vbk-065-a1',auteur:'u8',datum:'2026-05-26T03:32:00',rA:{u1:5},rAdv:{},body:`Stel de herkomst van de middelen vast. Vraag een schenkingsverklaring en bankafschriften van de schenker en van de ontvangst. Kijk of het land op een lijst van hoog-risicolanden staat, dan geldt verscherpt cliëntenonderzoek. Leg vast welke documenten je hebt ontvangen en hoe je de herkomst hebt beoordeeld.`},
   {id:'vbk-065-a2',auteur:'u4',datum:'2026-05-26T10:22:00',rA:{u8:4},rAdv:{u8:3},body:`Houd rekening met extra tijd. De geldverstrekker en de notaris stellen vaak dezelfde vragen, dus lever de stukken in één keer goed aan.`}
  ]},
 {id:'vbk-066',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-29T16:30:00',views:56,tags:['telefonisch advies','rente','vastlegging'],beste:'vbk-066-a1',
  titel:'Hoe documenteer ik telefonisch advies over een rentewijziging?',
  body:`Klanten bellen geregeld om te vragen of ze hun rente vroegtijdig moeten vastzetten. Hoe leggen jullie dat soort korte adviezen vast?`,
  antwoorden:[
   {id:'vbk-066-a1',auteur:'u1',datum:'2026-05-30T02:45:00',rA:{u4:5},rAdv:{u2:4,u5:3,u6:3,u7:3},body:`Maak na het gesprek een korte notitie in het CRM met de vraag, de relevante situatie van de klant, je advies en de reden. Stuur de klant een korte bevestiging per e-mail. Zo heb je ook bewijs dat de klant het advies ontving. Als het advies verder gaat dan een korte vraag, plan je een vervolggesprek.`},
   {id:'vbk-066-a2',auteur:'u6',datum:'2026-05-30T05:19:00',rA:{},rAdv:{},body:`Maak een vaste notitiesjabloon voor telefoongesprekken in het CRM. Dan vergeet niemand de kernpunten.`}
  ]},
 {id:'vbk-067',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-31T07:55:00',views:93,tags:['provisieverbod','beloning','Wft'],beste:null,
  titel:'Provisieverbod bij complexe producten: wat valt eronder?',
  body:`Een nieuwe collega vraagt of we voor een overlijdensrisicoverzekering bij een hypotheek nog provisie mogen ontvangen. Hoe zit dat?`,
  antwoorden:[
   {id:'vbk-067-a1',auteur:'u8',datum:'2026-06-01T02:30:00',rA:{u2:3,u3:4,u4:4,u6:5},rAdv:{u3:4,u5:3,u6:4},body:`Voor complexe producten en een aantal andere producten, waaronder hypotheken en verzekeringen die daaraan gekoppeld zijn, geldt een provisieverbod. De klant betaalt dan direct voor het advies en de bemiddeling. Controleer per product in de actuele regelgeving of het onder het verbod valt. Zorg dat je dienstverleningsdocument en opdrachtbevestiging duidelijk maken hoe je beloond wordt.`}
  ]},
 {id:'vbk-068',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-05T09:40:00',views:8,tags:['klachten','verwachtingen','communicatie'],beste:'vbk-068-a1',
  titel:'Klant is ontevreden over de looptijd van het traject',
  body:`Een klant klaagt dat de aanvraag te lang duurde, terwijl de vertraging bij de geldverstrekker lag. Hoe pak ik zo een klacht aan?`,
  antwoorden:[
   {id:'vbk-068-a1',auteur:'u4',datum:'2026-06-05T23:38:00',rA:{},rAdv:{u1:5,u2:5,u3:5,u5:4},body:`Neem de klacht serieus en volg je klachtenregeling, ook als de oorzaak niet bij jou lag. Leg uit wat er gebeurde en wanneer je de klant op de hoogte hield. Kijk kritisch of je de verwachtingen vooraf goed hebt gemanaged. Leg de klacht en de afhandeling vast in de klachtenregistratie.`}
  ]},
 {id:'vbk-069',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-09T07:45:00',views:446,tags:['digitaal advies','robo-advies','zorgplicht'],beste:'vbk-069-a1',
  titel:'Toezicht op digitale hypotheekadvies-tools',
  body:`We overwegen een online tool die klanten een eerste indicatie geeft. Wanneer wordt dat advies en welke eisen gelden dan?`,
  antwoorden:[
   {id:'vbk-069-a1',auteur:'u8',datum:'2026-06-09T10:33:00',rA:{u4:5,u6:4},rAdv:{u4:3,u6:3,u7:3},body:`Zodra de tool een persoonlijke aanbeveling geeft op basis van de situatie van de klant, is het advies en gelden dezelfde zorgplichten als bij een adviseur. Een indicatie van de maximale hypotheek is iets anders dan een aanbeveling voor een product. Zorg dat de tool duidelijk communiceert wat het wel en niet is. Leg vast hoe de tool is getest en wie de uitkomsten controleert.`},
   {id:'vbk-069-a2',auteur:'u6',datum:'2026-06-10T05:50:00',rA:{u5:3,u7:4},rAdv:{u4:3},body:`Test de tool met verschillende klantprofielen en bewaar die testresultaten. Bij elke update van de rekenregels herhaal je dat.`},
   {id:'vbk-069-a3',auteur:'u1',datum:'2026-06-10T07:47:00',rA:{u4:4,u6:3},rAdv:{u2:4,u6:5,u7:3},body:`Klanten lezen een indicatie vaak als een toezegging. Een duidelijke disclaimer en een vervolgafspraak met een adviseur zijn echt nodig.`}
  ]},
 {id:'vbk-070',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-13T16:40:00',views:110,tags:['dienstverleningsdocument','zakelijk','informatie'],beste:null,
  titel:'Wat zet je in een dienstverleningsdocument voor zakelijke klanten?',
  body:`We adviseren ook ondernemers over zakelijke verzekeringen. Kunnen we hetzelfde dienstverleningsdocument gebruiken als voor particulieren?`,
  antwoorden:[
   {id:'vbk-070-a1',auteur:'u3',datum:'2026-06-14T13:43:00',rA:{},rAdv:{u2:3,u5:5,u8:3},body:`In grote lijnen wel, maar controleer of de onderwerpen kloppen voor de zakelijke dienstverlening, zoals hoe je beloond wordt en welke verzekeraars je gebruikt. Zakelijke klanten verwachten vaak andere afspraken over service en schademelding. Het is overzichtelijker om een aparte versie te maken.`}
  ]},
 {id:'vbk-071',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-16T17:30:00',views:188,tags:['Wwft','identificatie','actualisatie'],beste:'vbk-071-a1',
  titel:'Wanneer moet ik een klant opnieuw identificeren?',
  body:`Een klant uit 2015 komt terug voor een nieuwe hypotheek. Zijn identiteitsbewijs in ons dossier is verlopen. Moet ik hem opnieuw identificeren?`,
  antwoorden:[
   {id:'vbk-071-a1',auteur:'u8',datum:'2026-06-16T19:18:00',rA:{u1:3,u7:3},rAdv:{u3:5,u6:4,u7:3},body:`Bij een nieuwe dienst aan een bestaande klant actualiseer je het cliëntenonderzoek op basis van risico. Een verlopen identiteitsbewijs is een goede reden om opnieuw te identificeren en te verifiëren. Werk ook de overige klantgegevens bij. Leg vast wanneer je de actualisatie deed en wat er veranderde.`},
   {id:'vbk-071-a2',auteur:'u1',datum:'2026-06-16T21:32:00',rA:{u2:5,u3:5,u6:3,u8:5},rAdv:{},body:`De geldverstrekker vraagt hoe dan ook een geldig identiteitsbewijs, dus ik doe het altijd opnieuw.`}
  ]},
 {id:'vbk-072',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-20T20:45:00',views:189,tags:['scheiding','passend advies','betaalbaarheid'],beste:'vbk-072-a1',
  titel:'Advies voor een gescheiden partner die de woning wil overnemen',
  body:`Een cliënte wil na een scheiding de woning overnemen. Haar inkomen is net voldoende, mede dankzij partneralimentatie. Wat leg ik extra vast?`,
  antwoorden:[
   {id:'vbk-072-a1',auteur:'u5',datum:'2026-06-21T00:23:00',rA:{u2:5},rAdv:{u4:5},body:`Kijk naar de duur van de partneralimentatie en wat er gebeurt als die stopt. Toets of de lasten daarna nog betaalbaar zijn en maak een scenario voor die situatie. Controleer de voorwaarden van de geldverstrekker voor het meetellen van alimentatie. Leg het scenario en de afspraken uit het echtscheidingsconvenant vast in het dossier.`},
   {id:'vbk-072-a2',auteur:'u2',datum:'2026-06-21T14:49:00',rA:{u4:4,u6:4},rAdv:{u1:4,u3:5,u5:3,u8:4},body:`Neem ook de verdeling van de overwaarde en de fiscale gevolgen mee. Dat is vaak complexer dan de hypotheek zelf.`}
  ]},
 {id:'vbk-073',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-24T19:45:00',views:534,tags:['AFM','rapportage','uitvraag'],beste:null,
  titel:'Rapportage aan de AFM: wie is verantwoordelijk?',
  body:`De jaarlijkse uitvraag van de AFM komt eraan. Ons kantoor heeft geen compliance officer. Wie moet die invullen?`,
  antwoorden:[
   {id:'vbk-073-a1',auteur:'u8',datum:'2026-06-25T10:40:00',rA:{u1:4,u5:4,u6:4},rAdv:{u4:4,u6:5},body:`De vergunninghouder is verantwoordelijk, en daarmee de dagelijks beleidsbepalers. Volgens de AFM zijn de beleidsbepalers persoonlijk verantwoordelijk voor het volledig, juist en naar waarheid invullen van de Marktmonitor adviseurs en bemiddelaars (MMAB). Iemand anders mag de uitvraag voorbereiden, maar een beleidsbepaler moet de antwoorden controleren en indienen. Een compliance officer is voor een klein kantoor niet altijd verplicht.
- Wijs een vaste persoon aan die de gegevens verzamelt: aantallen klanten, producten, omzet en beloningsvormen, klachten.
- Laat de beleidsbepaler de antwoorden controleren voordat ze worden ingediend via het AFM-portaal.
- Bewaar een kopie van de ingediende uitvraag en de bronbestanden.
- Let op de deadline: in 2026 was dat zes weken vanaf je eigen startdatum. Meewerken is verplicht (artikel 5:20 Awb); te laat of onjuist indienen kan leiden tot een waarschuwing of een last onder dwangsom.
- Controleer de omzetvraag extra zorgvuldig: die is ook de maatstaf voor je bijdrage aan de toezichtkosten.
Zet de uitvraag in je compliancekalender, zodat het niet afhangt van één persoon.`}
  ]},
 {id:'vbk-074',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-28T09:50:00',views:415,tags:['aflossingsvrij','oversluiten','passend advies'],beste:'vbk-074-a1',
  titel:'Advies over aflossingsvrij bij een leningdeel van voor 2013',
  body:`Een klant heeft een aflossingsvrij leningdeel uit een oude hypotheek. Hij wil verhuizen en dat deel meenemen. Wat moet ik extra bespreken?`,
  antwoorden:[
   {id:'vbk-074-a1',auteur:'u4',datum:'2026-06-28T15:55:00',rA:{u1:4},rAdv:{u5:5,u6:5,u7:3},body:`Bespreek dat er aan het einde van de looptijd een restschuld blijft als hij niet aflost, en hoe hij die wil oplossen. Bekijk of de lasten en de restschuld ook na pensionering te dragen zijn. Controleer de voorwaarden van de geldverstrekker voor het meenemen van het leningdeel en de fiscale gevolgen. Leg je analyse en de keuze van de klant vast.`},
   {id:'vbk-074-a2',auteur:'u5',datum:'2026-06-28T21:34:00',rA:{u2:3,u8:5},rAdv:{u2:5,u3:5,u6:4,u8:5},body:`Laat de klant ook zien wat gedeeltelijk aflossen per maand kost. Dat maakt het abstracte risico concreet.`}
  ]},
 {id:'vbk-075',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-01T08:55:00',views:410,tags:['AFM','leidraad','dossier'],beste:'vbk-075-a1',
  titel:'Wat verandert er met de nieuwe AFM-leidraad voor ons dossier?',
  body:`Er wordt veel gesproken over de nieuwe leidraad van de AFM voor hypotheekadvisering. Wat betekent dit concreet voor hoe wij dossiers opbouwen?`,
  antwoorden:[
   {id:'vbk-075-a1',auteur:'u8',datum:'2026-07-02T02:15:00',rA:{u1:3},rAdv:{},body:`Lees de leidraad zelf en bespreek hem in je team, want samenvattingen leggen soms andere accenten. Rode draad in de verwachtingen van de AFM is al jaren dat het advies aantoonbaar aansluit bij de persoonlijke situatie van de klant en dat de motivatie niet uit standaardteksten bestaat. Gebruik de leidraad als checklist naast een paar recente dossiers en kijk waar je afwijkt. Leg vast welke aanpassingen je in werkwijze en templates doet.`},
   {id:'vbk-075-a2',auteur:'u6',datum:'2026-07-02T16:57:00',rA:{u1:4,u2:3,u3:3,u8:4},rAdv:{u1:5},body:`Controleer of de leverancier van je adviespakket de templates aanpast. Vaak komt er een update, maar je eigen standaardteksten moet je zelf herzien.`}
  ]},
 {id:'vbk-076',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-06T19:20:00',views:203,tags:['motivatie','adviesrapport','leidraad'],beste:'vbk-076-a1',
  titel:'Motivatie per adviesonderwerp: hoe uitgebreid moet het zijn?',
  body:`In ons rapport staat per onderwerp vaak maar één zin motivatie. Is dat voldoende of verwacht de toezichthouder meer?`,
  antwoorden:[
   {id:'vbk-076-a1',auteur:'u5',datum:'2026-07-07T01:57:00',rA:{u3:5,u7:4},rAdv:{},body:`Het gaat niet om de lengte maar om de koppeling. De motivatie moet laten zien waarom deze keuze bij deze klant past, met verwijzing naar zijn doelen, financiële situatie en risicobereidheid. Eén goede zin kan genoeg zijn als die echt specifiek is. Een algemene zin die in elk dossier staat, is dat niet.`},
   {id:'vbk-076-a2',auteur:'u8',datum:'2026-07-07T23:37:00',rA:{u4:5,u6:3},rAdv:{u2:4},body:`Toets je motivatie zo: zou deze zin ook in het dossier van een willekeurige andere klant kunnen staan? Dan is hij te algemeen.`}
  ]},
 {id:'vbk-077',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-08T21:40:00',views:312,tags:['risicobereidheid','hypotheekvorm','klantprofiel'],beste:'vbk-077-a1',
  titel:'Risicoprofiel van de klant bij de keuze voor een hypotheekvorm',
  body:`Hoe leg ik de risicobereidheid van de klant vast als het gaat om de keuze tussen annuïtair, lineair en deels aflossingsvrij?`,
  antwoorden:[
   {id:'vbk-077-a1',auteur:'u1',datum:'2026-07-08T22:54:00',rA:{u6:4,u7:5},rAdv:{u5:4},body:`Bespreek concrete scenario's: wat gebeurt er met de schuld en de maandlast in elke vorm, en hoe voelt de klant zich daarbij. Laat de klant zelf aangeven welke risico's hij acceptabel vindt. Noteer zijn antwoorden in eigen woorden en koppel ze in het rapport aan de gekozen vorm. Leg ook vast welke alternatieven je hebt besproken.`},
   {id:'vbk-077-a2',auteur:'u5',datum:'2026-07-09T20:20:00',rA:{u4:3,u8:3},rAdv:{u1:3,u3:3},body:`Ik toon altijd de schuld op de pensioendatum per variant. Dat maakt de keuze voor de meeste klanten heel helder.`}
  ]},
 {id:'vbk-078',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-12T11:40:00',views:552,tags:['execution only','verzekering','vastlegging'],beste:null,
  titel:'Execution only bij een verzekering: wat moeten we vastleggen?',
  body:`Een klant wil zelf een overlijdensrisicoverzekering kiezen en alleen dat wij hem aanvragen. Hoe leggen we vast dat we niet adviseren?`,
  antwoorden:[
   {id:'vbk-078-a1',auteur:'u3',datum:'2026-07-13T04:45:00',rA:{u2:3,u7:3},rAdv:{u2:4,u5:3,u7:4},body:`Leg vast dat de klant uitdrukkelijk geen advies wil en zelf het product heeft gekozen. Wijs hem erop dat je dan niet toetst of het product passend is. Laat hem dat bevestigen. Let op dat je in het gesprek niet alsnog adviseert, want dan geldt de volledige zorgplicht.`},
   {id:'vbk-078-a2',auteur:'u8',datum:'2026-07-13T20:37:00',rA:{u2:4,u3:3,u5:3,u6:5},rAdv:{u3:5},body:`Controleer bij een verzekering gekoppeld aan een hypotheek of de klant voor de hypotheek wel advies kreeg. Dan is het lastig om voor het bijbehorende product geen advies te geven.`}
  ]},
 {id:'vbk-079',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-16T10:05:00',views:344,tags:['werkloosheid','risico','advies'],beste:'vbk-079-a1',
  titel:'Inkomensverlies bij werkloosheid: hoe concreet bespreken?',
  body:`Moet ik bij elke hypotheek het risico van werkloosheid met een berekening onderbouwen, ook als de klant een vast contract heeft?`,
  antwoorden:[
   {id:'vbk-079-a1',auteur:'u4',datum:'2026-07-16T17:08:00',rA:{u1:3,u5:4},rAdv:{},body:`Ja, het risico bespreek je bij elke klant, ook met een vast contract. Een berekening met een WW-uitkering maakt de gevolgen concreet. Bespreek welke buffers de klant heeft en hoe lang hij de lasten kan dragen. Leg de uitkomst en de keuze van de klant vast, ook als die besluit geen maatregelen te nemen.`}
  ]},
 {id:'vbk-080',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-21T11:55:00',views:339,tags:['AVG','communicatie','beveiliging'],beste:'vbk-080-a1',
  titel:'Collega gebruikt WhatsApp voor klantcontact',
  body:`Een collega stuurt klanten via WhatsApp op zijn privételefoon foto's van salarisstroken en offertes. Is dat toegestaan?`,
  antwoorden:[
   {id:'vbk-080-a1',auteur:'u8',datum:'2026-07-21T13:32:00',rA:{u3:3,u7:5},rAdv:{u1:4,u5:5,u7:3},body:`Dit is risicovol. Je hebt weinig controle over de gegevens op een privételefoon en ze komen niet in het dossier terecht. Maak een duidelijk beleid over welke kanalen zijn toegestaan en waarvoor. Gevoelige documenten horen in een beveiligde omgeving met vastlegging in het dossier. Bespreek het met de collega en laat de gegevens van de telefoon verwijderen nadat ze correct zijn opgeslagen.`},
   {id:'vbk-080-a2',auteur:'u6',datum:'2026-07-22T05:41:00',rA:{u2:4,u3:5},rAdv:{u3:5},body:`Er zijn zakelijke berichtendiensten die je kunt koppelen aan het CRM. Dan kun je klanten toch snel bedienen.`}
  ]},
 {id:'vbk-081',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-22T07:35:00',views:178,tags:['bewaartermijn','dossier','AVG'],beste:null,
  titel:'Hoe lang bewaar ik een adviesdossier na het afsluiten?',
  body:`Ons archief groeit enorm. Is er een vaste termijn voor het bewaren van adviesdossiers van hypotheken?`,
  antwoorden:[
   {id:'vbk-081-a1',auteur:'u8',datum:'2026-07-22T21:02:00',rA:{u3:3,u5:4},rAdv:{u4:3},body:`Er is niet één wettelijke termijn voor het hele adviesdossier. Veel kantoren bewaren het zolang het product loopt plus een periode daarna, omdat klachten en aansprakelijkheid lang na het advies nog kunnen spelen. Bepaal een termijn die je kunt onderbouwen en leg die vast in je bewaarbeleid. Voor de Wwft-gegevens geldt een eigen termijn.`},
   {id:'vbk-081-a2',auteur:'u2',datum:'2026-07-23T01:54:00',rA:{},rAdv:{},body:`Overleg ook met je beroepsaansprakelijkheidsverzekeraar. Die heeft er vaak een duidelijke mening over.`}
  ]},
 {id:'vbk-082',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-25T09:45:00',views:158,tags:['AVG','geheimhouding','samenwerking'],beste:'vbk-082-a1',
  titel:'Mag ik een collega-adviseur uit een ander kantoor in een dossier laten meekijken?',
  body:`Ik wil een complex dossier anoniem voorleggen aan een collega bij een ander kantoor. Wat mag wel en niet?`,
  antwoorden:[
   {id:'vbk-082-a1',auteur:'u8',datum:'2026-07-25T12:08:00',rA:{u2:3,u3:3,u4:5,u5:4},rAdv:{u2:3,u4:3,u6:4},body:`Echt anoniem voorleggen is prima: zonder naam, adres, geboortedatum of andere details waarmee iemand herkenbaar is. Let op unieke combinaties van gegevens die iemand toch herleidbaar maken. Wil je het volledige dossier delen, dan heb je toestemming van de klant of een andere grondslag nodig. Noteer in het dossier dat je het hebt voorgelegd en wat dat opleverde.`}
  ]},
 {id:'vbk-083',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-30T07:15:00',views:436,tags:['bewindvoerder','AVG','informatie'],beste:'vbk-083-a1',
  titel:'Verplicht reageren op een verzoek van een curator of bewindvoerder',
  body:`Een bewindvoerder vraagt om informatie over de hypotheek en verzekeringen van een klant. Mag ik die gegevens zomaar delen?`,
  antwoorden:[
   {id:'vbk-083-a1',auteur:'u8',datum:'2026-07-30T23:23:00',rA:{u6:4},rAdv:{u4:3},body:`Vraag eerst om de beschikking waaruit de benoeming en de reikwijdte van het bewind blijken. Een beschermingsbewindvoerder is bevoegd voor de goederen die onder bewind staan, dus controleer of dit daaronder valt. Verstrek alleen wat nodig is. Leg de beschikking en wat je hebt verstrekt vast in het dossier.`},
   {id:'vbk-083-a2',auteur:'u3',datum:'2026-07-31T01:27:00',rA:{},rAdv:{u2:5,u4:3},body:`Zet in het CRM een duidelijke markering dat er een bewindvoerder is, zodat collega's niet per ongeluk met de klant zelf afspraken maken.`}
  ]},
 {id:'vbk-084',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-03T13:20:00',views:150,tags:['uitkering','inkomen','passend advies'],beste:null,
  titel:'Klant ontvangt een uitkering: passend advies voor een hypotheek?',
  body:`Een klant heeft een blijvende arbeidsongeschiktheidsuitkering en wil een woning kopen. Kan ik dit adviseren en wat leg ik vast?`,
  antwoorden:[
   {id:'vbk-084-a1',auteur:'u5',datum:'2026-08-04T01:25:00',rA:{},rAdv:{u1:5,u6:4},body:`Dat kan, mits het inkomen duurzaam is en de lasten betaalbaar zijn. Kijk naar de aard van de uitkering, de verwachte duur en de herbeoordelingen. Controleer de voorwaarden van de geldverstrekker voor het meetellen van uitkeringen. Leg de stukken en je beoordeling van de duurzaamheid vast.`}
  ]},
 {id:'vbk-085',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-07T17:50:00',views:46,tags:['eigen middelen','Wwft','controle'],beste:'vbk-085-a1',
  titel:'Hoe ver ga je in het controleren van de eigen middelen?',
  body:`Een klant heeft een fors bedrag aan eigen middelen. Hij zegt dat hij het al jaren spaart. Volstaat een recent bankafschrift?`,
  antwoorden:[
   {id:'vbk-085-a1',auteur:'u4',datum:'2026-08-08T11:42:00',rA:{u1:5,u2:3,u5:4},rAdv:{u5:5,u7:4},body:`Een recent saldo laat zien dat het geld er is, maar niet waar het vandaan komt. Bij een bedrag dat niet past bij het inkomen of de leeftijd van de klant vraag je door, bijvoorbeeld met afschriften van een langere periode. Dit hoort bij het cliëntenonderzoek. Leg vast welke stukken je hebt gezien.`},
   {id:'vbk-085-a2',auteur:'u8',datum:'2026-08-09T03:02:00',rA:{u2:4,u3:4,u5:3,u6:4},rAdv:{u1:4},body:`Gebruik een risicogebaseerde aanpak: hoe groter de afwijking van het verwachte patroon, hoe dieper je kijkt.`}
  ]},
 {id:'vbk-086',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-11T09:20:00',views:66,tags:['adviesfee','transparantie','adviesrapport'],beste:null,
  titel:'Verplichte vermelding van de adviesfee in het adviesrapport',
  body:`Moet de hoogte van de fee ook in het adviesrapport staan als hij al in de opdrachtbevestiging staat?`,
  antwoorden:[
   {id:'vbk-086-a1',auteur:'u8',datum:'2026-08-12T08:45:00',rA:{u1:4,u4:4},rAdv:{u1:5,u5:4,u6:4},body:`De wettelijke verplichting draait om informatie vooraf: de klant moet voordat de dienstverlening begint weten wat het advies kost. Dat doe je met de vergelijkingskaart (sinds 1 april 2023 de opvolger van het dienstverleningsdocument, uiterlijk te geven voordat je advies geeft) en de opdrachtbevestiging. Een herhaling in het adviesrapport is niet expliciet voorgeschreven, maar ik raad het wel aan.
- In het rapport hoort een overzicht van de totale kosten van het advies, inclusief de fee, zodat de klant het advies en de kosten in samenhang ziet.
- Controleer dat de bedragen in opdrachtbevestiging, rapport en factuur gelijk zijn. Verschillen leveren vragen op bij klachten.
- Is de fee tussentijds gewijzigd, bijvoorbeeld door extra werk, leg dan vast dat de klant daarmee akkoord ging.
Bewaar de getekende opdrachtbevestiging bij het rapport in het dossier.`}
  ]},
 {id:'vbk-087',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-14T18:50:00',views:480,tags:['partner','geheimhouding','dossier'],beste:'vbk-087-a1',
  titel:'Klant geeft partner geen inzicht in de hypotheek',
  body:`Een klant wil een tweede hypotheek op de woning, maar vraagt mij zijn partner niet te informeren. De partner is mede-eigenaar. Wat nu?`,
  antwoorden:[
   {id:'vbk-087-a1',auteur:'u8',datum:'2026-08-15T15:15:00',rA:{u4:3,u6:3,u7:3},rAdv:{u1:5},body:`Als de partner mede-eigenaar is, heeft de geldverstrekker vrijwel altijd de medewerking van die partner nodig, en vaak ook bij een gemeenschap van goederen. Je kunt dit dus niet buiten de partner om regelen. Leg de klant uit dat je niet kunt adviseren op deze manier. Leg het gesprek en je besluit vast.`},
   {id:'vbk-087-a2',auteur:'u1',datum:'2026-08-16T01:02:00',rA:{},rAdv:{u3:5,u5:3,u8:3},body:`Ik zou dit ook als signaal zien. Bespreek het intern voordat je verder gaat.`}
  ]},
 {id:'vbk-088',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-15T16:25:00',views:580,tags:['duurzaamheid','voorkeuren','advies'],beste:'vbk-088-a1',
  titel:'Effect van duurzaamheidsvoorkeuren in het advies',
  body:`Een klant wil zijn spaargeld beleggen in duurzame fondsen naast de hypotheek. Moet ik duurzaamheidsvoorkeuren uitvragen?`,
  antwoorden:[
   {id:'vbk-088-a1',auteur:'u2',datum:'2026-08-16T09:30:00',rA:{u1:5,u5:5,u6:3,u7:4},rAdv:{u3:3,u4:4,u6:3,u8:5},body:`Bij beleggingsadvies moet je naar duurzaamheidsvoorkeuren vragen en ze meenemen in je advies. Leg vast wat de klant aangaf en hoe het geadviseerde product daarbij aansluit. Als een product niet aansluit, bespreek je dat en leg je de keuze van de klant vast. Controleer welke informatie de aanbieder over de duurzaamheidskenmerken geeft.`}
  ]},
 {id:'vbk-089',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-21T11:25:00',views:81,tags:['offerte','advies','zorgplicht'],beste:null,
  titel:'Hoe gaan jullie om met de nieuwe klant die al een offerte heeft?',
  body:`Een klant heeft zelf al een offerte aangevraagd en wil dat ik alleen nog de aanvraag afrond. Is dat advies of bemiddeling zonder advies?`,
  antwoorden:[
   {id:'vbk-089-a1',auteur:'u1',datum:'2026-08-21T15:19:00',rA:{u3:4,u4:3,u5:4,u8:4},rAdv:{},body:`Dat hangt af van wat je doet. Als je alleen administratief afrondt en niets toetst, is het bemiddeling zonder advies en moet de klant dat bewust kiezen. Maar zodra je een oordeel geeft over de offerte, adviseer je. Bespreek met de klant wat hij wil en leg het vast in de opdrachtbevestiging.`},
   {id:'vbk-089-a2',auteur:'u8',datum:'2026-08-21T18:57:00',rA:{},rAdv:{u3:4,u4:5,u5:4,u7:3},body:`Controleer of je kantoorbeleid execution only voor hypotheken toestaat en onder welke voorwaarden. Veel kantoren doen het niet.`}
  ]},
 {id:'vbk-090',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-24T10:50:00',views:314,tags:['pensioen','vroegpensioen','betaalbaarheid'],beste:'vbk-090-a1',
  titel:'Pensioenadvies en hypotheek bij een vroegpensioen',
  body:`Een klant wil op zijn zestigste stoppen met werken en tegelijk zijn hypotheek oversluiten. Hoe toets ik de betaalbaarheid?`,
  antwoorden:[
   {id:'vbk-090-a1',auteur:'u7',datum:'2026-08-25T04:10:00',rA:{u1:4,u2:3,u5:3},rAdv:{u3:4},body:`Breng het inkomen in de periode tot de AOW in kaart, en ook na de AOW. Kijk naar het gevolg van eerder opnemen van pensioen op de hoogte van de uitkering. Toets de lasten in elke fase. Leg de inkomensbronnen per periode en je berekening vast.`},
   {id:'vbk-090-a2',auteur:'u5',datum:'2026-08-25T16:43:00',rA:{u1:5,u6:3},rAdv:{},body:`Controleer ook de voorwaarden van de geldverstrekker voor inkomen na pensionering. Die kunnen per partij verschillen.`}
  ]},
 {id:'vbk-091',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-27T08:40:00',views:118,tags:['overlijden','dossier','nabestaanden'],beste:'vbk-091-a1',
  titel:'Klant overlijdt tijdens het adviestraject',
  body:`Een klant is overleden terwijl het advies nog liep. De partner wil verder. Wat moet ik doen met het dossier en de gegevens?`,
  antwoorden:[
   {id:'vbk-091-a1',auteur:'u5',datum:'2026-08-28T02:16:00',rA:{u1:4,u2:4,u4:4,u6:3},rAdv:{u8:5},body:`Rond het lopende advies niet af op naam van de overledene. Begin een nieuw traject met de partner, met een nieuwe inventarisatie. Leg vast wanneer je het overlijden vernam en hoe je het hebt afgehandeld. Wees zorgvuldig in de communicatie, de partner is in een kwetsbare situatie.`},
   {id:'vbk-091-a2',auteur:'u3',datum:'2026-08-28T03:19:00',rA:{},rAdv:{u4:5,u5:4,u6:5,u8:5},body:`Check ook of er lopende verzekeringen waren die een uitkering geven. Dat beïnvloedt de nieuwe situatie direct.`}
  ]},
 {id:'vbk-092',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-30T09:20:00',views:375,tags:['klachtenregeling','website','informatie'],beste:null,
  titel:'Klachtenregeling op de website verplicht?',
  body:`Moeten we onze klachtenregeling op de website publiceren of is het genoeg om die op verzoek te verstrekken?`,
  antwoorden:[
   {id:'vbk-092-a1',auteur:'u8',datum:'2026-08-31T09:30:00',rA:{u1:4,u5:4,u6:4},rAdv:{u4:4,u6:5},body:`Je moet de klant in elk geval informeren over je interne klachtenprocedure en over Kifid (artikel 4:17 Wft en het BGfo). Dat doe je meestal via de informatie die de klant vooraf krijgt, zoals je vergelijkingskaart (die sinds april 2023 het dienstverleningsdocument vervangt) of je algemene voorwaarden. Daarnaast geldt voor ondernemers die bij een geschilleninstantie zijn aangesloten dat ze die instantie ook vermelden op hun website, als ze er een hebben. Controleer de actuele eisen bij Kifid of je compliance officer.
In de praktijk is publiceren op de website de eenvoudigste weg:
- Zet de klachtenregeling als pagina of PDF online, met contactgegevens en termijnen.
- Vermeld duidelijk de aansluiting bij Kifid.
- Verwijs ernaar in je vergelijkingskaart en algemene voorwaarden.
Houd versiebeheer bij, zodat je kunt aantonen welke regeling gold op het moment van een klacht.`}
  ]},
 {id:'vbk-093',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-04T12:10:00',views:448,tags:['adviesrapport','bewijs','akkoord'],beste:'vbk-093-a1',
  titel:'Hoe toon ik aan dat de klant het rapport heeft gelezen?',
  body:`Klanten tekenen het rapport vaak zonder het te lezen. Hoe zorg ik dat ik kan aantonen dat de klant de inhoud echt begreep?`,
  antwoorden:[
   {id:'vbk-093-a1',auteur:'u5',datum:'2026-09-04T15:59:00',rA:{u2:4,u6:4,u7:3,u8:5},rAdv:{u6:3,u7:3},body:`Bespreek het rapport samen in een afsluitend gesprek en noteer de belangrijkste vragen die de klant stelde. Laat de klant ook samenvatten wat hij gaat doen. Een handtekening alleen is beperkt bewijs; de notitie van het gesprek versterkt dat. Houd het rapport overzichtelijk met een samenvatting vooraan.`},
   {id:'vbk-093-a2',auteur:'u8',datum:'2026-09-05T06:43:00',rA:{u3:5},rAdv:{u2:4,u3:3},body:`Gebruik begrijpelijke taal. Een rapport dat alleen voor de toezichthouder geschreven is, is niet klantgericht.`}
  ]},
 {id:'vbk-094',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-07T15:05:00',views:372,tags:['betalingsachterstand','BKR','zorgplicht'],beste:'vbk-094-a1',
  titel:'Advies aan een klant met een betalingsachterstand',
  body:`Een klant met een betalingsachterstand op zijn huidige hypotheek wil oversluiten om lagere lasten te krijgen. Kan ik daarbij adviseren?`,
  antwoorden:[
   {id:'vbk-094-a1',auteur:'u4',datum:'2026-09-07T19:26:00',rA:{u2:5},rAdv:{u1:3,u6:3,u7:5},body:`Ja, maar wees voorzichtig. Breng in kaart waardoor de achterstand ontstond en of de oorzaak is opgelost. Controleer de acceptatiecriteria van de geldverstrekker, want een achterstand kan aanvraag in de weg staan. Wijs de klant ook op het tijdig contact zoeken met de huidige geldverstrekker. Leg je analyse vast.`},
   {id:'vbk-094-a2',auteur:'u5',datum:'2026-09-08T12:47:00',rA:{u6:5},rAdv:{u7:4,u8:5},body:`Soms is een aanpassing bij de huidige geldverstrekker beter dan oversluiten. Bespreek beide routes.`}
  ]},
 {id:'vbk-095',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-09T14:55:00',views:231,tags:['AI','AVG','dossier'],beste:null,
  titel:'Gebruik van AI in het adviesproces',
  body:`We willen AI gebruiken om gespreksverslagen te maken. Waar moeten we op letten?`,
  antwoorden:[
   {id:'vbk-095-a1',auteur:'u6',datum:'2026-09-10T02:29:00',rA:{u2:4,u7:5},rAdv:{u4:4,u5:4,u7:4,u8:4},body:`Kijk waar de gegevens worden verwerkt en of je een verwerkersovereenkomst met de leverancier hebt. Kies een oplossing die klantgegevens niet gebruikt om modellen te trainen. Controleer elk verslag voordat het in het dossier komt, de adviseur blijft verantwoordelijk. Informeer klanten over het gebruik.`},
   {id:'vbk-095-a2',auteur:'u8',datum:'2026-09-10T23:33:00',rA:{},rAdv:{u2:4,u5:5},body:`Neem het op in je verwerkingsregister en doe een risicoanalyse, en bij een hoog risico een DPIA.`}
  ]},
 {id:'vbk-096',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-14T20:25:00',views:418,tags:['vakbekwaamheid','stagiair','begeleiding'],beste:'vbk-096-a1',
  titel:'Mag een stagiair klantgesprekken voeren?',
  body:`We hebben een stagiair die graag zelf gesprekken wil voeren. Onder welke voorwaarden mag dat?`,
  antwoorden:[
   {id:'vbk-096-a1',auteur:'u8',datum:'2026-09-15T10:40:00',rA:{u1:4,u2:5,u5:4,u7:5},rAdv:{u1:4,u3:3},body:`Een stagiair zonder de vereiste diploma's mag geen zelfstandig advies geven. Hij mag wel meekijken of onder directe begeleiding werkzaamheden uitvoeren, afhankelijk van de regels voor werken onder verantwoordelijkheid van een vakbekwame adviseur. Controleer de actuele regels en leg de begeleiding vast. Het advies blijft van de begeleidende adviseur.`}
  ]},
 {id:'vbk-097',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-17T14:45:00',views:72,tags:['screening','integriteit','personeel'],beste:'vbk-097-a1',
  titel:'Integriteitsscreening van nieuwe medewerkers',
  body:`We nemen een nieuwe adviseur aan. Welke screening moeten we doen en wat leggen we vast?`,
  antwoorden:[
   {id:'vbk-097-a1',auteur:'u8',datum:'2026-09-17T20:49:00',rA:{u1:4},rAdv:{u1:3},body:`Bij medewerkers in integriteitsgevoelige functies vraag je onder meer een verklaring omtrent het gedrag en controleer je referenties en diploma's. Leg de screening vast in het personeelsdossier en bepaal hoe vaak je herhaalt. Controleer ook of de medewerker de eed of belofte financiële sector moet afleggen en zorg dat dat gebeurt.`}
  ]},
 {id:'vbk-098',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-20T16:50:00',views:565,tags:['afwijkend advies','duurzaamheid','vastlegging'],beste:'vbk-098-a1',
  titel:'Afwijkend advies bij een klant die niet wil verduurzamen',
  body:`Ik adviseer een budget voor verduurzaming mee te financieren, maar de klant wil dat niet. Is dat een afwijking van mijn advies?`,
  antwoorden:[
   {id:'vbk-098-a1',auteur:'u1',datum:'2026-09-21T12:12:00',rA:{u2:3,u6:3},rAdv:{},body:`Als je het expliciet adviseert en de klant kiest anders, is het een afwijking. Leg vast wat je adviseerde, waarom, en dat de klant bewust anders kiest. Het is meestal geen risico dat de klant in een onverantwoorde situatie brengt, dus een korte vastlegging volstaat. Bespreek wel dat het later meefinancieren andere voorwaarden kan hebben.`}
  ]},
 {id:'vbk-099',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-23T12:05:00',views:129,tags:['AFM','onderzoek','dossier'],beste:null,
  titel:'Wat doen we als de AFM een dossier opvraagt?',
  body:`We kregen een verzoek van de AFM om een aantal dossiers aan te leveren. Hoe bereiden we ons voor?`,
  antwoorden:[
   {id:'vbk-099-a1',auteur:'u8',datum:'2026-09-24T08:50:00',rA:{u1:5,u4:4,u5:5},rAdv:{u1:5,u5:4,u6:4},body:`Lever volledig en op tijd aan, en pas niets aan in de dossiers. Meewerken aan een informatieverzoek van de AFM is verplicht (artikel 5:20 Awb). Achteraf aanvullen of wijzigen is een groot risico; als er iets ontbreekt, benoem dat liever eerlijk.
- Noteer de deadline en wie contactpersoon is. Vraag bij onduidelijkheid direct na bij de AFM wat precies wordt gevraagd.
- Exporteer de gevraagde dossiers volledig: inventarisatie, klantprofiel, berekeningen, adviesrapport, correspondentie en offertes.
- Maak een overzicht per dossier met de inhoud en eventuele toelichting.
- Laat een tweede persoon controleren of alles compleet en leesbaar is.
- Stuur alleen wat gevraagd wordt, via het kanaal dat de AFM aangeeft.
Bewaar een kopie van wat is aangeleverd. Gebruik eventuele bevindingen daarna om je werkwijze te verbeteren en leg die maatregelen vast.`}
  ]},
 {id:'vbk-100',cat:'comp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-27T21:50:00',views:300,tags:['communicatie','informatieverstrekking','klantbelang'],beste:'vbk-100-a1',
  titel:'Klant wil geen digitale communicatie',
  body:`Een oudere klant wil alles op papier ontvangen. Ons proces is volledig digitaal. Moeten we daar rekening mee houden?`,
  antwoorden:[
   {id:'vbk-100-a1',auteur:'u3',datum:'2026-09-28T04:42:00',rA:{u7:4},rAdv:{u7:5},body:`Ja, je informatie moet de klant bereiken op een manier die hij kan gebruiken. Stuur de belangrijkste stukken op papier en leg de afspraak vast in het CRM. Zorg dat het dossier wel compleet digitaal is.`},
   {id:'vbk-100-a2',auteur:'u6',datum:'2026-09-28T08:28:00',rA:{u1:5,u2:4,u3:3,u7:3},rAdv:{u4:3,u5:4},body:`In de meeste systemen kun je een communicatievoorkeur per klant instellen. Dan zien collega's het meteen.`}
  ]}
]);
